-- Targeted TCF Reading distractor polish. 11_14: only 4 immutable banks, 2 questions per bank.
-- Original passages, stems, keys, weights, UI, prior versions, attempts and progress retained.
begin;
select pg_advisory_xact_lock(hashtext('tcf-reading-distractor-polish-20261119'));
create temp table cleanup_before on commit drop as
select (select count(*) from academy_tcf_reading.papers) as banks,
 (select count(*) from academy_tcf_reading.attempts) as attempts,
 (select md5(coalesce(string_agg(to_jsonb(a)::text,'' order by id),'')) from academy_tcf_reading.attempts a) as attempts_digest,
 (select md5(coalesce(string_agg(to_jsonb(p)::text,'' order by id,version),'')) from academy_tcf_reading.papers p) as banks_digest;
create temp table cleanup_other_pointers on commit drop as
select test_id,version from academy_tcf_reading.published_papers where test_id not in ('tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14');
create temp table cleanup_scope(test_id text,changed integer[]) on commit drop;
insert into cleanup_scope values
('tcf-reading-11',array[33,36]::integer[]),
('tcf-reading-12',array[32,34]::integer[]),
('tcf-reading-13',array[26,33]::integer[]),
('tcf-reading-14',array[32,34]::integer[]);
do $preflight$ begin
 if (select count(*) from academy_tcf_reading.published_papers)<>20 then raise exception 'Expected 20 published reading papers'; end if;
 if (select count(*) from academy_tcf_reading.published_papers where test_id between 'tcf-reading-01' and 'tcf-reading-06' and version='tcf-reading-2026-11-close-reading-v6')<>6 then raise exception 'Tests 01-06 changed'; end if;
 if (select count(*) from academy_tcf_reading.published_papers where test_id between 'tcf-reading-07' and 'tcf-reading-10' and version='tcf-reading-2026-11-distractor-polish-v5')<>4 then raise exception 'Earlier cleanup batch pointer changed'; end if;
 if (select count(*) from academy_tcf_reading.published_papers where test_id in ('tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14') and version='tcf-reading-2026-11-close-reading-v4')<>4 then raise exception 'Expected exactly 4 original v4 catalog pointers'; end if;
 if (select count(*) from academy_tcf_reading.papers where id in ('tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14') and version='tcf-reading-2026-11-distractor-polish-v5')<>0 then raise exception 'Target new versions already exist'; end if;
 if exists (select 1 from (values
('tcf-reading-11','ebeb9d148bd2699686f09bc54f915f07'),
('tcf-reading-12','87a9f6c166d503d9d71643d1e664205a'),
('tcf-reading-13','26dc42a93eb86e3c9af377048ceaaadd'),
('tcf-reading-14','69c2850e8881ca7e312a77909f6b8723')
) as expected(id,digest)
 join academy_tcf_reading.papers p on p.id=expected.id and p.version='tcf-reading-2026-11-close-reading-v4'
 where md5(p.content::text)<>expected.digest) then raise exception 'Published source bank digest changed since editorial inspection'; end if;
end $preflight$;
insert into academy_tcf_reading.papers(id,version,content) values
('tcf-reading-11','tcf-reading-2026-11-distractor-polish-v5',$paper_11${"id":"tcf-reading-11","title":"TCF Reading · Test 11","seconds":3600,"version":"tcf-reading-2026-11-distractor-polish-v5","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"C","options":["Des meubles démontés","Des aliments ouverts","Des couvertures propres","Des vêtements mouillés"],"passage":"La collecte de couvertures se termine samedi. Déposez uniquement des articles propres et secs ; les vêtements seront collectés le mois prochain.\n\nLes articles non adaptés ne doivent pas être laissés devant le local.","question":"Que peut-on donner cette semaine ?","explanation":"Le passage indique : « La collecte de couvertures se termine samedi. Déposez uniquement des articles propres et secs ; les vêtements seront collectés le mois prochain. » Cela justifie la réponse : Des couvertures propres."},{"number":2,"points":3,"correct":"D","options":["Tous les matins","Le dimanche soir","Le lundi seulement","Le jeudi"],"passage":"La permanence d'entraide reçoit sans rendez-vous le jeudi. Les autres jours, un appel préalable est nécessaire.\n\nMerci de prévoir un temps d'attente pendant les périodes de forte fréquentation.","question":"Quand peut-on venir directement ?","explanation":"Le passage indique : « La permanence d'entraide reçoit sans rendez-vous le jeudi. Les autres jours, un appel préalable est nécessaire. » Cela justifie la réponse : Le jeudi."},{"number":3,"points":3,"correct":"D","options":["Les musiciens du soir uniquement","Tous les convives","Les clients du marché","Les bénévoles chargés de l'installation"],"passage":"Les bénévoles du repas partagé se retrouveront à neuf heures pour installer les tables. Le public arrivera à midi.\n\nLes personnes inscrites pour une autre mission garderont leur horaire habituel de présence.","question":"Qui est attendu à neuf heures ?","explanation":"Le passage indique : « Les bénévoles du repas partagé se retrouveront à neuf heures pour installer les tables. Le public arrivera à midi. » Cela justifie la réponse : Les bénévoles chargés de l'installation."},{"number":4,"points":3,"correct":"A","options":["La confirmation d'inscription","Un billet de spectacle","Un relevé bancaire","Un diplôme scolaire"],"passage":"La distribution de cahiers est ouverte aux familles inscrites. Apportez votre confirmation, imprimée ou sur téléphone.\n\nLe personnel retrouvera ensuite votre dossier sans demander une nouvelle inscription. Une famille rencontrant une difficulté peut contacter l'accueil avant le jour prévu.","question":"Quel document faut-il présenter ?","explanation":"Le passage indique : « La distribution de cahiers est ouverte aux familles inscrites. Apportez votre confirmation, imprimée ou sur téléphone. » Cela justifie la réponse : La confirmation d'inscription."},{"number":5,"points":9,"correct":"C","options":["Un service de transport privé","Une absence d'activité","Une tâche sans port de charges lourdes","Un changement de tous les horaires"],"passage":"Je peux aider à trier les dons samedi, mais pas porter les cartons lourds. Peux-tu me prévoir une tâche à table ?\n\nJe suis disponible toute la matinée et peux aussi aider à vérifier les étiquettes. Ainsi, l'équipe pourra répartir les autres tâches entre les bénévoles disponibles.","question":"Quelle adaptation est demandée ?","explanation":"Le passage indique : « Je peux aider à trier les dons samedi, mais pas porter les cartons lourds. Peux-tu me prévoir une tâche à table ? » Cela justifie la réponse : Une tâche sans port de charges lourdes."},{"number":6,"points":9,"correct":"B","options":["Uniquement un comédien professionnel","Une personne intéressée par la lecture partagée","Une personne refusant de lire à voix haute","Un vendeur de livres seulement"],"passage":"Notre association cherche des personnes pour lire des histoires. Il suffit d'aimer partager des textes ; aucune expérience de spectacle n'est exigée.\n\nUne séance d'accueil permettra de découvrir les livres et de préparer une première lecture.","question":"Quel profil convient ?","explanation":"Le passage indique : « Notre association cherche des personnes pour lire des histoires. Il suffit d'aimer partager des textes ; aucune expérience de spectacle n'est exigée. » Cela justifie la réponse : Une personne intéressée par la lecture partagée."},{"number":7,"points":9,"correct":"C","options":["Annuler toutes les inscriptions","Calculer le prix des repas","Organiser les équipes de deux","Modifier le lieu du festival"],"passage":"Merci de confirmer votre disponibilité avant mardi. Nous devons constituer les binômes d'accompagnement, pas simplement compter les inscrits.\n\nUne absence peut être signalée sans devoir fournir de détail personnel au groupe. Il faut surtout que le responsable puisse rechercher un remplaçant assez tôt.","question":"Pourquoi la confirmation est-elle importante ?","explanation":"Le passage indique : « Merci de confirmer votre disponibilité avant mardi. Nous devons constituer les binômes d'accompagnement, pas simplement compter les inscrits. » Cela justifie la réponse : Organiser les équipes de deux."},{"number":8,"points":9,"correct":"C","options":["Remplacer les dons par un impôt","Réserver tous les articles aux touristes","Soutenir le fonctionnement solidaire","Supprimer les tarifs adaptés"],"passage":"La boutique solidaire vend aussi au grand public. Ces achats contribuent à financer les tarifs adaptés proposés à certaines familles.\n\nLe prix annoncé au public correspond aussi au travail de tri, d'entretien et d'accueil nécessaire au fonctionnement du lieu.","question":"Quel rôle jouent les achats ordinaires ?","explanation":"Le passage indique : « La boutique solidaire vend aussi au grand public. Ces achats contribuent à financer les tarifs adaptés proposés à certaines familles. » Cela justifie la réponse : Soutenir le fonctionnement solidaire."},{"number":9,"points":9,"correct":"A","options":["Une disponibilité moins fréquente mais fiable","Une participation sans calendrier","Un arrêt de toute aide","Une présence quotidienne"],"passage":"Je préfère m'engager une fois par mois régulièrement plutôt que promettre chaque semaine et annuler souvent.\n\nNous pourrons revoir le calendrier si mes disponibilités changent, plutôt que laisser l'équipe découvrir une absence le jour même.","question":"Quelle forme d'engagement est choisie ?","explanation":"Le passage indique : « Je préfère m'engager une fois par mois régulièrement plutôt que promettre chaque semaine et annuler souvent. » Cela justifie la réponse : Une disponibilité moins fréquente mais fiable."},{"number":10,"points":9,"correct":"C","options":["Attribuer un diplôme professionnel","Présenter les dossiers personnels au public","Préparer l'entrée dans l'activité","Sélectionner les donateurs les plus riches"],"passage":"L'équipe propose une séance d'accueil avant la première mission. Les nouveaux bénévoles y découvriront les règles de confidentialité.\n\nLes volontaires pourront poser leurs questions avant de s'engager. Les responsables présenteront aussi les limites des tâches et les situations qui demandent de contacter une personne compétente.","question":"À quoi sert cette séance ?","explanation":"Le passage indique : « L'équipe propose une séance d'accueil avant la première mission. Les nouveaux bénévoles y découvriront les règles de confidentialité. » Cela justifie la réponse : Préparer l'entrée dans l'activité."},{"number":11,"points":15,"correct":"C","options":["Seuls les professionnels peuvent participer","Le revenu détermine le nombre d'heures","Une même durée a la même valeur","Les outils sont vendus aux voisins"],"passage":"Une association échange des services entre habitants. Une heure de jardinage donne droit à une heure d'aide, quelle que soit la valeur marchande habituelle du métier.\n\nLes participants indiquent les services qu'ils peuvent proposer et les moments où ils sont disponibles. Un coordinateur facilite les premières rencontres sans promettre une réponse immédiate à chaque demande. Les échanges sont enregistrés dans un carnet commun pour que chacun sache ce qu'il a donné et reçu. Le groupe souhaite reconnaître des compétences diverses, y compris des gestes ordinaires parfois peu valorisés.","question":"Quel principe régit l'échange ?","explanation":"Le passage indique : « Une association échange des services entre habitants. Une heure de jardinage donne droit à une heure d'aide, quelle que soit la valeur marchande habituelle du métier. » Cela justifie la réponse : Une même durée a la même valeur."},{"number":12,"points":15,"correct":"D","options":["Remplacer les décisions des bénéficiaires","Éviter toute explication","Confisquer les documents personnels","Renforcer la compréhension des démarches"],"passage":"Le centre social aide à remplir des formulaires, mais demande aux personnes de rester présentes. Les animateurs expliquent les démarches plutôt que décider à leur place.\n\nLes animateurs montrent où trouver une information et demandent aux personnes de vérifier ce qui les concerne. L'aide peut prendre plus de temps qu'une saisie rapide effectuée sans explication. Le centre considère cependant que cette présence permet aussi de préparer une prochaine démarche.","question":"Quel objectif accompagne l'aide immédiate ?","explanation":"Le passage indique : « Le centre social aide à remplir des formulaires, mais demande aux personnes de rester présentes. Les animateurs expliquent les démarches plutôt que décider à leur place. » Cela justifie la réponse : Renforcer la compréhension des démarches."},{"number":13,"points":15,"correct":"D","options":["Supprimer les rencontres","Attirer des visiteurs payants","Empêcher toute coordination interne","Préserver la confidentialité"],"passage":"Une maraude adapte son parcours aux besoins signalés. Les bénévoles ne publient pas les lieux de rencontre pour protéger les personnes accompagnées.\n\nLes personnes choisissent ce qu'elles souhaitent dire et peuvent refuser une rencontre. L'équipe note seulement les informations nécessaires au suivi, dans un document non accessible au public. Les nouveaux volontaires reçoivent une présentation de ces règles avant leur première sortie. L'association souhaite favoriser un contact régulier sans transformer la situation d'une personne en contenu destiné à attirer de nouveaux donateurs. Les récits utilisés pour présenter le projet seront préparés séparément, avec un accord explicite des personnes concernées par la publication.","question":"Pourquoi limiter ces informations publiques ?","explanation":"Le passage indique : « Une maraude adapte son parcours aux besoins signalés. Les bénévoles ne publient pas les lieux de rencontre pour protéger les personnes accompagnées. » Cela justifie la réponse : Préserver la confidentialité."},{"number":14,"points":15,"correct":"A","options":["Une difficulté d'accès numérique","La durée des réparations","Le nombre de chaises","Le coût des outils professionnels"],"passage":"Un atelier de réparation réserve des places sans inscription en ligne. Les organisateurs veulent accueillir aussi ceux qui n'utilisent pas internet.\n\nUne partie des places reste réservée à un accueil sur place ou par téléphone. Les bénévoles expliquent ensuite comment préparer l'objet et quels renseignements apporter. Le service souhaite que la méthode d'inscription ne sélectionne pas à elle seule les participants. Les demandes seront suivies pour vérifier si ce choix touche réellement de nouvelles personnes. Il ne s'agit pas d'abandonner un outil pratique pour les habitués, mais de garder plusieurs voies possibles vers la même activité, dans des conditions clairement annoncées au public.","question":"Quelle barrière cherchent-ils à réduire ?","explanation":"Le passage indique : « Un atelier de réparation réserve des places sans inscription en ligne. Les organisateurs veulent accueillir aussi ceux qui n'utilisent pas internet. » Cela justifie la réponse : Une difficulté d'accès numérique."},{"number":15,"points":15,"correct":"B","options":["La publicité des dossiers","Le respect de la dignité","La sélection par la prise de parole","Le classement des difficultés"],"passage":"Une association fournit des repas sans demander aux personnes de raconter publiquement leur situation. L'accueil ne doit pas devenir une épreuve de justification devant les autres.\n\nLes bénéficiaires peuvent s'adresser discrètement à un responsable s'ils ont une demande particulière. Les bénévoles suivent une procédure commune pour éviter des pratiques très différentes selon la personne présente. L'association souhaite que la simplicité de l'accueil ne dépende pas d'une relation personnelle ou de la capacité à raconter une histoire convaincante. Elle vérifiera aussi les temps d'attente et l'organisation de la file.","question":"Quel principe est défendu ?","explanation":"Le passage indique : « Une association fournit des repas sans demander aux personnes de raconter publiquement leur situation. L'accueil ne doit pas devenir une épreuve de justification devant les autres. » Cela justifie la réponse : Le respect de la dignité."},{"number":16,"points":15,"correct":"A","options":["Clarifier les responsabilités lors du prêt","Garantir que rien ne s'abîmera jamais","Remplacer tous les échanges humains","Fixer un prix de vente obligatoire"],"passage":"Des voisins prêtent des objets grâce à un catalogue commun. Une fiche indique leur état au départ et au retour pour éviter les malentendus.\n\nL'emprunteur peut poser des questions avant de confirmer le prêt. Les organisateurs souhaitent préserver la confiance entre voisins sans attendre qu'un problème se transforme en accusation. Les règles précisent aussi ce qui se passe lorsqu'un objet s'abîme malgré une utilisation normale, afin de ne pas confondre tout incident avec une faute ou de promettre qu'un objet partagé restera toujours intact.","question":"À quoi sert cette fiche ?","explanation":"Le passage indique : « Des voisins prêtent des objets grâce à un catalogue commun. Une fiche indique leur état au départ et au retour pour éviter les malentendus. » Cela justifie la réponse : Clarifier les responsabilités lors du prêt."},{"number":17,"points":15,"correct":"D","options":["Les conversations sont interdites","Les visiteurs prescrivent des traitements","Les bénéficiaires doivent rester seuls","Les visites ne remplacent pas des soins"],"passage":"Une équipe organise des visites amicales. Les visiteurs ne réalisent pas de soins ; ils signalent les besoins particuliers au responsable compétent.\n\nLe programme prévoit surtout du temps pour discuter, lire ou faire une petite promenade lorsque cela convient. Les personnes accompagnées choisissent les activités et peuvent demander de reporter un rendez-vous. Le responsable distingue cette présence amicale des interventions nécessitant une formation ou une autorisation particulière. L'association préfère un cadre clair à une promesse d'aide illimitée, qui pourrait mettre en difficulté les visiteurs comme les personnes qu'ils viennent rencontrer.","question":"Quelle limite est posée ?","explanation":"Le passage indique : « Une équipe organise des visites amicales. Les visiteurs ne réalisent pas de soins ; ils signalent les besoins particuliers au responsable compétent. » Cela justifie la réponse : Les visites ne remplacent pas des soins."},{"number":18,"points":15,"correct":"A","options":["Élargir la participation aux échanges","Rendre les documents plus techniques","Réserver les décisions aux traducteurs","Supprimer les débats"],"passage":"Un collectif propose des réunions avec traduction dans plusieurs langues. Les comptes rendus restent courts pour que les informations circulent facilement.\n\nLes participants reçoivent les principaux documents avant la réunion et peuvent demander une précision pendant les échanges. Le comité souhaite que les personnes moins à l'aise dans une langue ne soient pas réduites à écouter sans intervenir. Les traducteurs ne prennent pas les décisions à leur place. Ils facilitent la compréhension de ce qui est proposé et des choix à effectuer.","question":"Quel objectif guide ces choix ?","explanation":"Le passage indique : « Un collectif propose des réunions avec traduction dans plusieurs langues. Les comptes rendus restent courts pour que les informations circulent facilement. » Cela justifie la réponse : Élargir la participation aux échanges."},{"number":19,"points":15,"correct":"B","options":["Éviter tout tri","Assurer la qualité des dons distribués","Réserver les jeux aux organisateurs","Augmenter leur prix de revente"],"passage":"Une collecte de jouets demande des jeux complets. Les pièces manquantes seront recherchées avant la distribution, afin d'offrir des objets réellement utilisables.\n\nLes bénévoles essaient les mécanismes et indiquent les limites lorsqu'un jeu ne peut pas être complété. Certains objets seront réparés avant d'être proposés, d'autres orientés vers une autre filière. Elle expliquera les critères de tri aux personnes qui apportent des jouets, afin de réduire les déplacements inutiles et de préparer les prochaines collectes dans de meilleures conditions.","question":"Pourquoi vérifier les jeux ?","explanation":"Le passage indique : « Une collecte de jouets demande des jeux complets. Les pièces manquantes seront recherchées avant la distribution, afin d'offrir des objets réellement utilisables. » Cela justifie la réponse : Assurer la qualité des dons distribués."},{"number":20,"points":21,"correct":"B","options":["Supprimer toute disponibilité bénévole","Prendre en compte des contraintes différentes","Fixer les horaires au hasard","Éviter de rencontrer les bénéficiaires"],"passage":"Une association consulte les bénéficiaires avant de choisir les horaires d'ouverture. Les créneaux pratiques pour les bénévoles ne sont pas toujours ceux qui conviennent aux personnes accueillies. Les personnes interrogées indiquent notamment les moments où elles peuvent se déplacer et les contraintes liées aux transports. L'association compare ces réponses avec les disponibilités de l'équipe avant de proposer un calendrier. Elle veut éviter qu'une permanence apparemment ouverte reste inaccessible à ceux qu'elle vise. Les horaires seront réexaminés après quelques semaines, en regardant les demandes non satisfaites autant que les présences effectivement enregistrées à l'accueil.","question":"Pourquoi cette consultation est-elle nécessaire ?","explanation":"Le passage indique : « Une association consulte les bénéficiaires avant de choisir les horaires d'ouverture. Les créneaux pratiques pour les bénévoles ne sont pas toujours ceux qui conviennent aux personnes accueillies. » Cela justifie la réponse : Prendre en compte des contraintes différentes."},{"number":21,"points":21,"correct":"D","options":["Les frais réels sont toujours nuls","Tous les déplacements sont des emplois","Les conducteurs paient les passagers","Rembourser une dépense n'est pas rémunérer un service"],"passage":"Un réseau de covoiturage solidaire rembourse les frais réels des conducteurs. Il ne cherche pas à leur procurer un revenu complémentaire. Les trajets et les dépenses doivent être notés selon les règles annoncées à l'inscription. L'association souhaite que les conducteurs n'avancent pas durablement des frais qu'ils ne peuvent pas supporter. Elle précise cependant que le dispositif reste différent d'une activité commerciale de transport. Les responsables vérifieront les documents sans demander aux bénéficiaires de négocier directement un prix à chaque sortie, afin de préserver un cadre compréhensible pour les deux parties.","question":"Quelle distinction est faite ?","explanation":"Le passage indique : « Un réseau de covoiturage solidaire rembourse les frais réels des conducteurs. Il ne cherche pas à leur procurer un revenu complémentaire. » Cela justifie la réponse : Rembourser une dépense n'est pas rémunérer un service."},{"number":22,"points":21,"correct":"B","options":["L'abandon du projet initial sans explication","La transparence envers les donateurs","Le refus de tout suivi","La recherche de nouveaux frais cachés"],"passage":"Une collecte financière réussit au-delà des prévisions. L'association publie l'utilisation du surplus au lieu de modifier discrètement l'objectif annoncé. Les responsables présentent les dépenses supplémentaires envisagées et expliquent leur lien avec le projet initial. Le comité souhaite que la réussite de la collecte ne rende pas son fonctionnement moins lisible. Une somme reçue au-delà de l'objectif reste une ressource à utiliser avec soin, selon des décisions identifiables, et non un montant dont l'emploi pourrait être laissé sans explication publique.","question":"Quel souci manifeste cette démarche ?","explanation":"Le passage indique : « Une collecte financière réussit au-delà des prévisions. L'association publie l'utilisation du surplus au lieu de modifier discrètement l'objectif annoncé. » Cela justifie la réponse : La transparence envers les donateurs."},{"number":23,"points":21,"correct":"C","options":["Éviter les intérêts personnels","Réserver le lieu aux nouveaux arrivants","Créer des relations qui dépassent le seul besoin d'aide","Transformer toutes les rencontres en démarches"],"passage":"Un café accueille des rencontres entre personnes arrivées récemment et habitants installés. Les échanges portent sur des centres d'intérêt partagés, pas uniquement sur les difficultés administratives. Des ateliers de musique, des promenades et des échanges de recettes servent de premiers points de rencontre. Les personnes peuvent venir sans devoir exposer immédiatement leur parcours. L'équipe veut que chacun puisse être reconnu pour ses intérêts et ses contributions, pas uniquement pour une difficulté. Les informations pratiques restent disponibles dans un autre cadre.","question":"Quel effet est recherché ?","explanation":"Le passage indique : « Un café accueille des rencontres entre personnes arrivées récemment et habitants installés. Les échanges portent sur des centres d'intérêt partagés, pas uniquement sur les difficultés administratives. » Cela justifie la réponse : Créer des relations qui dépassent le seul besoin d'aide."},{"number":24,"points":21,"correct":"A","options":["De l'aide pour intégrer les bénévoles","Une rémunération automatique de tous les volontaires","Un remplacement de leur activité par des annonces","Une suppression des missions"],"passage":"Une plateforme met en relation des bénévoles et des associations. Les petites structures souhaitent aussi un accompagnement, car publier une mission ne suffit pas à organiser l'accueil des volontaires. Les coordinateurs doivent présenter la mission, expliquer les limites et prévoir un interlocuteur pour le premier jour. Les structures peu nombreuses n'ont pas toujours le temps de préparer seules ces éléments. Elles demandent donc un soutien qui dépasse la simple visibilité de leur annonce.","question":"Quel besoin complémentaire expriment-elles ?","explanation":"Le passage indique : « Une plateforme met en relation des bénévoles et des associations. Les petites structures souhaitent aussi un accompagnement, car publier une mission ne suffit pas à organiser l'accueil des volontaires. » Cela justifie la réponse : De l'aide pour intégrer les bénévoles."},{"number":25,"points":21,"correct":"C","options":["Les missions d'accueil devraient surtout compter pour les bénévoles qui ne peuvent participer aux travaux agricoles réguliers.","L'expérience botanique peut devenir la mesure principale lorsque l'organisation administrative des parcelles est assurée.","La seule contribution physique, au détriment de la coordination et de l'accueil, au sein du jardin.","La contribution doit être rapportée au temps de travail visible, les tâches de planning restant un soutien complémentaire."],"passage":"Un jardin collectif attribue des tâches adaptées aux capacités de chacun. L'association reconnaît aussi l'organisation et l'accueil comme des contributions, pas seulement le travail physique. Les membres discutent des tâches avant chaque période importante, puis peuvent changer de rôle. Certaines personnes connaissent les plantes, d'autres savent accueillir un nouveau voisin ou tenir le planning. L'association souhaite éviter qu'une même forme de contribution devienne la mesure unique de l'engagement. Un membre ne peut pas bêcher mais coordonne les plannings et aide à résoudre les conflits d'horaires; sans lui, les plantations seraient retardées. Les responsables comptabilisent aussi cette contribution quand ils répartissent les responsabilités.","question":"Quel critère d'engagement le jardin refuse-t-il de privilégier exclusivement ?","explanation":"C identifie le critère purement physique que le jardin refuse d'imposer seul. A réserve la reconnaissance de l'accueil à certains bénévoles; B privilégie la botanique; D fait du travail visible la référence alors que la coordination des plannings est essentielle."},{"number":26,"points":21,"correct":"B","options":["Elle confie aux personnes accueillies le choix du stock à commander pour la semaine selon leurs besoins exprimés.","Elle ouvre des choix informés dans la limite des stocks disponibles, avec des explications adaptées aux familles.","Elle étend la gamme de produits distribués sans modifier la manière dont les bénévoles orientent les décisions.","Elle facilite surtout les choix des personnes qui maîtrisent déjà la préparation des produits disponibles."],"passage":"Une banque alimentaire forme ses équipes à expliquer les choix disponibles. Les personnes accompagnées peuvent exprimer leurs préférences dans les limites du stock. Les bénévoles présentent les aliments et les conditions de conservation sans supposer que toutes les familles les utilisent de la même manière. L'équipe ne promet pas un choix sans limite, mais veut que les possibilités réelles soient expliquées et que les personnes ne soient pas simplement destinataires d'une décision prise sans elles. Le stock contient deux céréales que certaines familles ne savent pas préparer de la même façon. Une bénévole explique les usages et laisse la personne choisir, sans garantir que chaque produit sera toujours disponible.","question":"Que modifie cette pratique dans la relation d'aide ?","explanation":"B associe information et choix possible dans les limites du stock. A attribue aux bénéficiaires des commandes non prévues; C déplace le changement vers l'assortiment; D laisse les novices exclus contrairement à l'exemple."},{"number":27,"points":21,"correct":"D","options":["Elle permet aux fondateurs d'assurer seuls une continuité stable en confiant aux autres des tâches moins importantes.","Elle transforme les permanences en engagements spontanés, sans prévoir de relais lors des absences.","Elle rend les nouveaux bénévoles indépendants de toute formation supplémentaire après lecture des fiches.","Elle réduit la dépendance à quelques membres détenant les informations essentielles, lors des absences imprévues."],"passage":"Un groupe souhaite pérenniser ses actions après une urgence locale. Il organise un calendrier et répartit les responsabilités pour éviter que tout repose sur deux fondateurs. Les fondateurs préparent des fiches simples et accompagnent les nouveaux responsables lors des premières permanences. Ils souhaitent que l'information circule au lieu de rester dans quelques téléphones personnels. Les membres pourront signaler les tâches trop lourdes avant de se décourager. Lorsque l'un des fondateurs tombe malade, les nouvelles fiches permettent de maintenir les permanences avec une autre équipe. Les documents servent d'appui à une transmission effective, non de remplacement à tout accompagnement.","question":"Pourquoi la transmission des tâches est-elle centrale pour la pérennité du groupe ?","explanation":"D limite la dépendance à quelques membres. A conserve cette concentration; B supprime les remplacements nécessaires; C confond documentation et absence de tout accompagnement."},{"number":28,"points":21,"correct":"D","options":["Un récit détaillé permet d'estimer l'impact moyen des interventions qui appartiennent à la même catégorie.","Les témoignages devraient remplacer les tableaux lorsque les interventions administratives semblent équivalentes.","Le témoignage le plus significatif peut illustrer le résultat typique du programme dès lors que la publication est autorisée.","Éclairer des effets particuliers sans généraliser à tous les bénéficiaires, dans les bilans des interventions réalisées."],"passage":"L'association ajoute des témoignages à son bilan chiffré. Une aide ponctuelle peut avoir un effet important que le seul nombre d'interventions ne décrit pas. Les récits sont recueillis avec l'accord des personnes et relus avant une éventuelle publication. Ils ne remplacent pas les données de suivi, mais aident à comprendre des effets que les tableaux résument mal. Le centre veut éviter de présenter chaque histoire comme représentative de toutes les situations. Le bilan compte dix interventions identiques, mais un témoignage décrit comment l'une d'elles a permis une reprise de démarches après des mois d'arrêt. L'association conserve le total et la description, sans généraliser ce résultat particulier à tous les cas.","question":"Que permet l'ajout de témoignages sans remplacer les chiffres ?","explanation":"D met en lumière un effet particulier sans le généraliser à toutes les interventions. A et C prêtent à un récit une représentativité non établie; B remplacerait les totaux que l'association veut justement conserver."},{"number":29,"points":21,"correct":"B","options":["La participation régulière aux activités constitue une condition pour bénéficier d'aides complémentaires plutôt que de l'accueil initial.","Recevoir une aide relève d'un droit d'accueil indépendant d'une éventuelle contribution volontaire, dans toutes les circonstances.","Les bénéficiaires proposant d'aider à l'accueil peuvent être prioritaires lorsque les services manquent de places.","Une personne devenue bénévole cesse d'être éligible aux aides puisque ses besoins sont supposés avoir diminué."],"passage":"Un centre propose de participer à l'organisation aux personnes qui viennent y chercher une aide. Cette possibilité est facultative et n'est pas une condition pour être accueilli. Les bénéficiaires peuvent proposer une activité, aider à un rangement ou participer à une réunion lorsqu'ils le souhaitent. Ils veulent préserver un droit à l'accueil tout en reconnaissant que les personnes reçues peuvent aussi contribuer à la vie du lieu. Une personne ne souhaite pas participer aux réunions mais a besoin d'un colis alimentaire. Le centre confirme que son accès ne changera pas; une autre personne choisit d'aider ponctuellement à l'accueil.","question":"Quelle distinction protège la liberté des personnes accompagnées ?","explanation":"B affirme l'indépendance de l'aide et du bénévolat. A/C réintroduisent des conditions d'accès, D invente une perte de droits liée à la participation."},{"number":30,"points":26,"correct":"C","options":["Prolonger la période de mobilisation renforcée afin de profiter de l'expérience des bénévoles déjà très investis.","Confier durablement aux fondateurs les tâches les plus exigeantes et proposer les autres missions au reste du groupe.","Prévoir relais et limites pour maintenir l'engagement sans épuiser les bénévoles, tout au long de l'année.","Privilégier des engagements très courts décidés au dernier moment pour respecter la liberté individuelle des bénévoles."],"passage":"L'engagement bénévole est parfois présenté comme un temps libre sans contraintes. Or une association doit aussi définir les limites des missions et reconnaître les indisponibilités. Une disponibilité généreuse mais sans cadre peut conduire à l'épuisement et compromettre la continuité de l'action. Les responsables prévoient des pauses, des relais et un interlocuteur en cas de difficulté. Ces règles ne diminuent pas la générosité du projet ; elles lui permettent de rester possible quand les premières semaines d'enthousiasme sont passées. Une bénévole assure trois permanences supplémentaires en période d'urgence puis demande un relais. L'association organise une rotation, car maintenir cette disponibilité exceptionnelle pendant toute l'année l'épuiserait.","question":"Quel principe soutient la continuité du bénévolat après la phase d'urgence ?","explanation":"C formalise des relais et des limites. A/B prolongent la surcharge sur quelques personnes, D supprime une prévisibilité nécessaire à la continuité."},{"number":31,"points":26,"correct":"A","options":["Les distributions répondent aux besoins actuels, tandis qu'une action plus lente vise des causes structurelles, à terme.","L'aide d'urgence fournit des observations mais ne peut pas être utilisée pour discuter des causes de logement.","L'amélioration du logement constitue une étape préalable à toute distribution, afin d'éviter la répétition des besoins.","La quantité de colis distribués donne directement la mesure des progrès accomplis dans les conditions d'habitat."],"passage":"Une aide rapide répond à une urgence. Elle ne modifie pas nécessairement les causes qui rendent cette aide indispensable. Un collectif maintient ses distributions tout en participant à un travail sur l'accès au logement. Les deux démarches répondent à des temporalités différentes. Ils souhaitent continuer à répondre aux besoins présents, tout en utilisant ce qu'ils observent pour participer à des changements qui pourraient réduire la nécessité de ces interventions à l'avenir. Les distributions de nourriture répondent aux besoins de cette semaine, tandis que les données recueillies sur les difficultés de logement sont transmises à un groupe de travail. Les organisateurs refusent de présenter l'une des démarches comme substitut de l'autre.","question":"Quel lien le collectif établit-il entre distribution et action sur le logement ?","explanation":"A articule aide immédiate et action plus lente sur les causes. B nie la possibilité de transmission d'information; C reporte l'urgence, D confond activité et changement structurel."},{"number":32,"points":26,"correct":"D","options":["Le comparer aux confirmations de créneau pour mesurer l'écart entre intérêt initial et disponibilité probable.","Le rapprocher des présences effectives pour distinguer les intentions initiales des engagements réellement tenus pendant la première semaine.","L'utiliser comme liste de contacts à solliciter pour confirmer les disponibilités avant d'établir le calendrier des permanences.","Le présenter comme un effectif disponible garanti pour couvrir les missions prévues, sans vérification préalable."],"passage":"Le nombre de volontaires inscrits sur une plateforme augmente. Les associations observent pourtant des présences irrégulières. Pour apprécier les ressources réelles, elles distinguent une intention d'engagement et une participation effectivement organisée. Les responsables proposent un accueil et une confirmation concrète des créneaux. Le passage d'une candidature à une présence régulière demande une organisation, même lorsque les personnes déclarent sincèrement vouloir aider et disposent de compétences utiles à l'association. Cent profils sont créés en ligne, mais seuls trente volontaires confirment un créneau et dix se présentent la première semaine. L'association cherche à comprendre cette conversion sans supposer que les soixante-dix autres sont insincères.","question":"Quel usage du nombre d'inscriptions serait trompeur ?","explanation":"D ferait des cent profils inscrits un effectif disponible garanti, malgré seulement trente confirmations et dix présences. A, B et C proposent au contraire de distinguer profils, engagements effectifs et contacts à relancer."},{"number":33,"points":26,"correct":"D","options":["Recueillir les avis puis expliquer les contraintes budgétaires, sans préciser leur effet sur les décisions.","Présenter les décisions retenues après la réunion en décrivant les difficultés techniques, mais sans revenir sur les suggestions des participants.","Discuter des propositions reçues et privilégier celles qui correspondent aux choix déjà envisagés avant la consultation des habitants.","Expliquer comment les propositions ont influencé les décisions et pourquoi, avec un retour sur les arbitrages."],"passage":"Une organisation souhaite « donner la parole » à ses bénéficiaires. Elle doit aussi leur laisser un effet sur les décisions. Recueillir des avis sans expliquer ce qui en sera fait peut transformer la consultation en simple illustration d'un projet déjà arrêté. Cette réponse permet aux participants d'apprécier la portée de leur contribution et de comprendre les contraintes, au lieu de disparaître après la réunion. Après une réunion, les habitants proposent deux changements. L'organisation explique qu'elle adopte le premier et reporte le second pour des raisons de sécurité documentées. Cette réponse permet de comprendre la portée de la consultation.","question":"Quelle pratique rend la consultation plus qu'une collecte symbolique d'opinions ?","explanation":"D demande un retour sur l'effet des propositions et les motifs d'arbitrage. A et B exposent des contraintes ou décisions sans relier celles-ci à la contribution des habitants; C réduit la consultation aux orientations déjà arrêtées."},{"number":34,"points":26,"correct":"B","options":["Parce qu'un accueil soigné peut réduire l'importance des contraintes budgétaires des personnes aidées.","Une présentation soignée peut respecter les clients et contribuer à la mission sociale, sans demander de justification personnelle.","Parce qu'une boutique agréable rend moins nécessaire l'accompagnement des clients dans leurs choix.","Parce que l'organisation ressemble davantage à un commerce ordinaire et peut donc adopter les mêmes objectifs de profit."],"passage":"Une boutique solidaire améliore sa présentation pour que les clients puissent choisir dans un lieu accueillant. Certains s'inquiètent qu'une belle vitrine fasse oublier la mission sociale. L'équipe répond que le respect des personnes peut aussi passer par la qualité ordinaire du service. Les clients peuvent consulter les prix et demander des informations sur les objets comme dans un autre commerce. La boutique présente les objets avec des prix lisibles et propose un conseil sans exiger que les clients expliquent leur situation. Les responsables estiment qu'une qualité d'accueil comparable à un commerce ordinaire peut faire partie du respect.","question":"Pourquoi une présentation soignée n'est-elle pas incompatible avec la mission sociale ?","explanation":"B considère la dignité de l'accueil comme compatible avec la mission sociale. A/C minimisent les besoins, D assimile apparence commerciale et finalité lucrative."},{"number":35,"points":26,"correct":"B","options":["À limiter les échanges informels aux membres les plus anciens afin de stabiliser les procédures communes.","À rendre l'organisation accessible aux nouveaux arrivants tout en conservant les relations d'entraide, malgré certaines absences.","À maintenir la transmission dans les messages personnels tout en ajoutant un guide pour les nouveaux.","À fixer les consignes initiales de manière durable sans prévoir de nouvelles discussions sur leur évolution."],"passage":"Le développement d'un réseau d'entraide augmente les demandes adressées aux coordinateurs. Pour durer, le groupe formalise certaines règles sans supprimer les échanges informels. Il cherche à préserver la confiance tout en rendant l'organisation moins dépendante de relations personnelles fragiles. Les nouveaux membres sauront où chercher une information et à qui poser une question, même lorsque les personnes qui les ont accueillis sont absentes. Une nouvelle coordinatrice trouve les consignes écrites même lorsque son mentor est absent, mais continue d'échanger librement avec l'équipe. Le réseau souhaite réduire la fragilité de la transmission sans formaliser chaque conversation.","question":"À quoi sert la formalisation partielle des règles ?","explanation":"B combine une documentation accessible aux nouveaux avec les relations informelles. A restreint les échanges, C maintient la dépendance aux personnes, D exclut l'ajustement pourtant recherché."},{"number":36,"points":33,"correct":"A","options":["Parce que les effets sociaux et la capacité de participation constituent aussi des résultats pertinents.","Parce que les progrès professionnels priment sur les relations sociales dans le bilan du centre.","Parce que la présence régulière permet de prévoir une insertion professionnelle future, sans attendre la signature d'un contrat.","Parce que le trimestre ne permet pas encore d'évaluer l'emploi, qui reste le critère principal de réussite du projet."],"passage":"Un projet associe des personnes précaires à des ateliers culturels. Les organisateurs refusent de mesurer le résultat uniquement par un retour à l'emploi. Les relations, la confiance et la possibilité de participer à une vie commune ont une valeur propre. L'utilité sociale ne se réduit pas toujours à un indicateur économique immédiat. Les participants peuvent parler d'un changement dans leurs relations ou de la possibilité de sortir plus facilement de chez eux. Certains envisagent ensuite une formation ou un emploi, d'autres recherchent surtout un espace où ils se sentent reconnus. Le centre souhaite décrire ces trajectoires sans les classer selon une seule issue. Il discutera donc des critères avec les personnes concernées avant de rédiger son bilan. Le projet peut avoir plusieurs effets utiles, dont certains apparaissent lentement et restent difficiles à résumer dans un chiffre unique présenté à la fin de l'année. Un atelier n'aboutit à aucun contrat de travail pendant le trimestre, mais plusieurs personnes auparavant isolées participent désormais à des rencontres et prennent part à des décisions du quartier. Le centre veut rendre ce changement visible dans son bilan.","question":"Pourquoi l'absence de contrat de travail ne suffit-elle pas à qualifier cet atelier d'échec ?","explanation":"A retient des effets sociaux observés, notamment la participation et les relations, indépendamment d'une embauche immédiate. B et D rétablissent l'emploi comme critère principal; C infère une embauche future de la fréquentation sans preuve."},{"number":37,"points":33,"correct":"A","options":["L'exigence d'une activité durable se heurte à une visibilité des ressources trop courte pour l'organiser.","Une formation longue donne aux financeurs la possibilité de suspendre les ressources au moment des évaluations.","Un financement annuel réduit les coûts administratifs mais rend plus difficile l'examen régulier des résultats.","L'incertitude financière vient surtout d'un manque de planification interne que les responsables peuvent corriger seuls."],"passage":"Une association dépend d'un financement annuel renouvelable. Elle peut annoncer beaucoup d'activités, mais hésite à former durablement son équipe sans visibilité. Les financeurs demandent de la stabilité aux actions qu'ils soutiennent. Cette stabilité devient difficile lorsque les ressources permettant de la construire restent elles-mêmes incertaines. Les responsables cherchent un calendrier de financement qui permette d'anticiper les embauches et la formation. Ils expliquent que le temps passé à reconstruire sans cesse des dossiers réduit aussi celui disponible pour l'accueil. Les financeurs souhaitent garder la possibilité d'évaluer les actions et de réorienter les soutiens. Le débat porte donc sur des engagements assez stables pour rendre l'activité possible, sans supprimer l'examen de ses résultats. Les associations veulent que cette incertitude soit visible dans le bilan, plutôt que les interruptions soient interprétées uniquement comme un défaut d'organisation interne. Le financeur souhaite des équipes formées et régulières, mais annonce le renouvellement de sa subvention seulement quelques semaines avant chaque échéance. L'association hésite alors à embaucher pour les missions qui demandent un an de préparation.","question":"Quel problème de cohérence le calendrier de financement crée-t-il ?","explanation":"A décrit la contradiction entre demande de stabilité et ressources trop incertaines pour la préparer. B/C ne correspondent pas au problème exposé; D attribue à l'association seule un défaut lié au calendrier du financeur."},{"number":38,"points":33,"correct":"B","options":["Un nouveau support de communication exige d'informer les témoins, mais l'accord initial couvre toutes les campagnes similaires.","L'accord porte sur un usage précis, non sur toutes les diffusions futures, dans une campagne nouvelle.","La première diffusion autorise les campagnes suivantes dès lors que les propos cités ne sont pas modifiés.","Le consentement donné pendant l'accompagnement vaut aussi pour des usages institutionnels ultérieurs, sous réserve d'anonymat."],"passage":"Un collectif publie les récits de personnes accompagnées pour sensibiliser le public. Il leur propose de relire les textes et de retirer leur accord avant diffusion. Le fait qu'un témoignage serve une cause utile ne supprime pas les droits de la personne dont il raconte l'expérience. L'objectif collectif ne dispense pas de respecter une décision individuelle de ne pas s'exposer. L'association présente plusieurs moyens de contribuer à la sensibilisation, dont certains ne montrent aucun visage ni détail personnel. Elle accepte qu'une personne préfère ne pas participer, sans changer l'aide qu'elle reçoit. Les responsables souhaitent éviter qu'un accord donné dans une situation fragile devienne une obligation ressentie. Avant chaque nouvelle utilisation, le cadre sera expliqué dans une langue compréhensible. La communication pourra ainsi servir le projet tout en conservant une place à la décision de chacun, y compris lorsqu'une histoire particulièrement émouvante semblerait très efficace pour mobiliser de futurs soutiens. Une histoire publiée avec accord initial est ensuite demandée par une autre campagne. L'association sollicite une nouvelle autorisation, car la première personne n'avait accepté qu'une utilisation délimitée.","question":"Que signifie ici le respect du consentement lors d'une nouvelle campagne ?","explanation":"B limite l'accord à l'usage consenti et reconnaît la possibilité d'une nouvelle décision. A/C supposent une autorisation plus étendue que celle donnée; D lie à tort l'aide à des utilisations futures."},{"number":39,"points":33,"correct":"A","options":["Des moyens de départ comparables ne suffisent pas: la capacité des partenaires à assurer l'accueil doit être reconstruite selon chaque territoire.","Des activités initiales de même nombre prouvent que les deux territoires appliquent le modèle avec une efficacité comparable dans la durée.","La différence observée démontre que les partenaires expliquent seuls la réussite, à l'exclusion d'autres conditions territoriales.","La communication locale peut assurer la continuité d'un lieu si les permanences initiales ont suscité un intérêt suffisant."],"passage":"Une initiative locale attire l'attention nationale. Ses responsables sont invités à reproduire partout le même modèle. Ils présentent les principes, mais soulignent les relations de confiance et les ressources particulières qui ont permis leur réussite. Transmettre une expérience ne signifie pas promettre qu'elle produira les mêmes effets sans adaptation. Ils proposent aux nouveaux groupes d'examiner les besoins, les partenaires et les disponibilités avant de reprendre les mêmes activités. Certaines règles pourront être conservées, tandis que d'autres devront changer selon les personnes accueillies. L'équipe souhaite rester utile sans transformer un succès local en formule universelle. Les échanges porteront aussi sur les difficultés rencontrées, pas seulement sur les résultats faciles à montrer. Cette démarche demande plus de temps qu'une copie rapide, mais permet de distinguer les principes transférables et les conditions particulières qui doivent être reconstruites dans le nouveau territoire. Dans une autre ville, l'association trouve des locaux comparables mais aucun partenaire capable d'assurer les permanences. Elle conserve le principe d'accueil libre et modifie le calendrier et les responsabilités au lieu de copier la formule initiale. Deux communes reprennent ensuite l'initiative en annonçant le même budget et des locaux semblables. Dans la première, une maison de quartier dispose déjà d'une équipe de médiateurs et d'accords avec les services sociaux; dans la seconde, les locaux restent souvent fermés faute de personnes pour recevoir les visiteurs. Les deux communes affichent pourtant un nombre d'activités comparable durant le premier mois, grâce à des bénévoles mobilisés exceptionnellement. Six mois plus tard, seule la première maintient des permanences régulières. L'équipe d'origine refuse de conclure que la seconde commune devrait simplement augmenter les dépenses de communication: elle propose d'identifier quels partenaires peuvent réellement assurer l'accueil et de modifier le calendrier en conséquence. Le rapport précise que la différence de continuité ne démontre pas, à elle seule, que chaque autre différence entre territoires est sans effet.","question":"Quelle leçon les deux implantations apportent-elles sur la transposition d'un modèle, sans généralisation abusive ?","explanation":"A distingue les moyens matériels comparables du réseau de partenaires nécessaire à des permanences durables. B infère trop du premier mois; C fait des partenaires l'unique cause sans preuve; D suppose que la communication peut remplacer l'organisation de l'accueil."}]}$paper_11$::jsonb),
('tcf-reading-12','tcf-reading-2026-11-distractor-polish-v5',$paper_12${"id":"tcf-reading-12","title":"TCF Reading · Test 12","seconds":3600,"version":"tcf-reading-2026-11-distractor-polish-v5","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"D","options":["Tous les champs privés","Le sentier des vergers","La cour de la ferme","Le chemin communal"],"passage":"Le sentier des vergers est fermé pendant la récolte. La promenade reste possible par le chemin communal.\n\nLes promeneurs sont invités à suivre les panneaux temporaires. La fermeture doit permettre le passage des équipes et du matériel sans gêne.","question":"Quel chemin reste accessible ?","explanation":"Le passage indique : « Le sentier des vergers est fermé pendant la récolte. La promenade reste possible par le chemin communal. » Cela justifie la réponse : Le chemin communal."},{"number":2,"points":3,"correct":"C","options":["Dormir dans l'étable","Visiter l'élevage","Acheter à la boutique","Participer aux naissances"],"passage":"La ferme ouvre sa boutique vendredi, mais les visites d'élevage reprendront seulement au printemps.\n\nL'équipe peut toutefois répondre aux questions sur les produits pendant les horaires de vente.","question":"Que peut-on faire vendredi ?","explanation":"Le passage indique : « La ferme ouvre sa boutique vendredi, mais les visites d'élevage reprendront seulement au printemps. » Cela justifie la réponse : Acheter à la boutique."},{"number":3,"points":3,"correct":"C","options":["Accompagner obligatoirement chaque visiteur","Courir librement dans les cultures","Rester attachés sur le chemin","Entrer dans tous les bâtiments"],"passage":"Les chiens sont acceptés sur le chemin s'ils restent en laisse. Ils ne doivent pas entrer dans les parcelles.\n\nCette consigne permet de maintenir l'accès public sans perturber le travail dans les champs voisins.","question":"Quelle règle concerne les chiens ?","explanation":"Le passage indique : « Les chiens sont acceptés sur le chemin s'ils restent en laisse. Ils ne doivent pas entrer dans les parcelles. » Cela justifie la réponse : Rester attachés sur le chemin."},{"number":4,"points":3,"correct":"A","options":["Dimanche pendant les horaires indiqués","Après seize heures dimanche","Tous les soirs","Uniquement en hiver"],"passage":"Le moulin reçoit les groupes sur réservation. Les visiteurs individuels peuvent venir dimanche entre dix et seize heures.\n\nLes groupes recevront une confirmation avec les conditions d'accueil. Les visites individuelles suivront le parcours ouvert et respecteront les espaces non accessibles au public.","question":"Quand une personne seule peut-elle venir sans réservation ?","explanation":"Le passage indique : « Le moulin reçoit les groupes sur réservation. Les visiteurs individuels peuvent venir dimanche entre dix et seize heures. » Cela justifie la réponse : Dimanche pendant les horaires indiqués."},{"number":5,"points":9,"correct":"A","options":["Protéger les jeunes plants du gel","Les laisser sans lumière pendant un mois","Les arroser avec de l'eau glacée","Les planter immédiatement dehors"],"passage":"Je te garderai les plants jusqu'à samedi. Mets-les à l'abri si le gel revient ; ils ne sont pas encore prêts pour la pleine terre.\n\nJe te préciserai quelles variétés supportent mieux le froid. Prévois quelques pots pour les garder temporairement près d'une fenêtre plutôt que les installer trop vite au jardin.","question":"Quelle précaution est conseillée ?","explanation":"Le passage indique : « Je te garderai les plants jusqu'à samedi. Mets-les à l'abri si le gel revient ; ils ne sont pas encore prêts pour la pleine terre. » Cela justifie la réponse : Protéger les jeunes plants du gel."},{"number":6,"points":9,"correct":"C","options":["Ils resteront obligatoirement au musée","Ils seront vendus aux visiteurs","Ils seront restitués après copie","Ils seront détruits après exposition"],"passage":"L'association recherche des photos anciennes du village. Les originaux seront numérisés puis rendus ; aucun don définitif n'est demandé.\n\nUne fiche permettra d'identifier les lieux et les personnes représentés lorsque ces informations sont connues. Les propriétaires pourront vérifier les légendes avant l'exposition.","question":"Que deviendront les documents prêtés ?","explanation":"Le passage indique : « L'association recherche des photos anciennes du village. Les originaux seront numérisés puis rendus ; aucun don définitif n'est demandé. » Cela justifie la réponse : Ils seront restitués après copie."},{"number":7,"points":9,"correct":"D","options":["Approcher seules les ruches","Renoncer à toute activité rurale","Apporter leur propre miel","Prévenir l'organisateur à l'avance"],"passage":"Nous visiterons les ruches avec un apiculteur. Les personnes sensibles aux piqûres doivent le signaler avant la sortie.\n\nUn équipement de protection sera présenté au groupe avant l'approche. Le responsable pourra proposer une autre manière de suivre l'activité si une situation demande davantage de précautions.","question":"Quelle démarche est demandée à certaines personnes ?","explanation":"Le passage indique : « Nous visiterons les ruches avec un apiculteur. Les personnes sensibles aux piqûres doivent le signaler avant la sortie. » Cela justifie la réponse : Prévenir l'organisateur à l'avance."},{"number":8,"points":9,"correct":"A","options":["Une récolte a subi un aléa météo","Tous les fruits ont été vendus à l'étranger","Les clients ont demandé uniquement des légumes","Le point de retrait est fermé"],"passage":"Le panier de cette semaine contient moins de fruits, mais davantage de légumes. La grêle a touché une partie du verger.\n\nLes quantités seront expliquées au point de retrait. Les producteurs vous remercient pour votre compréhension.","question":"Pourquoi le contenu change-t-il ?","explanation":"Le passage indique : « Le panier de cette semaine contient moins de fruits, mais davantage de légumes. La grêle a touché une partie du verger. » Cela justifie la réponse : Une récolte a subi un aléa météo."},{"number":9,"points":9,"correct":"B","options":["Des sandales de ville","Des chaussures adaptées à la boue","Des patins","Un masque de plongée"],"passage":"Apportez des bottes pour la visite : le chemin près des pâtures est boueux, même lorsque la cour semble sèche.\n\nNous marcherons aussi sur une partie du terrain pour découvrir les activités du jour.","question":"Quel équipement est recommandé ?","explanation":"Le passage indique : « Apportez des bottes pour la visite : le chemin près des pâtures est boueux, même lorsque la cour semble sèche. » Cela justifie la réponse : Des chaussures adaptées à la boue."},{"number":10,"points":9,"correct":"B","options":["Éviter toute rencontre","Limiter la fatigue liée à la chaleur","Terminer une livraison nocturne","Profiter d'une température plus élevée"],"passage":"Je préfère venir aider au désherbage tôt le matin. Ensuite, la chaleur rend le travail plus fatigant.\n\nJe pourrai ensuite aider à ranger le matériel avant de repartir. Cette organisation me permettra de travailler tranquillement sans devoir interrompre longtemps l'activité aux heures les plus difficiles.","question":"Pourquoi choisir cet horaire ?","explanation":"Le passage indique : « Je préfère venir aider au désherbage tôt le matin. Ensuite, la chaleur rend le travail plus fatigant. » Cela justifie la réponse : Limiter la fatigue liée à la chaleur."},{"number":11,"points":15,"correct":"B","options":["La suppression des plantes aquatiques","La préservation d'habitats particuliers","L'uniformité esthétique","La création d'un parking"],"passage":"Une commune conserve de petites mares malgré leur aspect parfois désordonné. Elles accueillent des espèces qui ne vivent pas dans les bassins décoratifs.\n\nLes agents ont prévu un entretien différent des abords, afin de ne pas retirer toute la végétation pendant une période sensible. Des panneaux expliqueront ce choix aux passants. La commune souhaite éviter que la présence de plantes irrégulières ou d'eau trouble soit automatiquement interprétée comme un abandon. Les habitants pourront alors découvrir les fonctions de ces lieux modestes, dont l'intérêt ne se voit pas toujours dans un paysage aménagé uniquement pour paraître propre sur une photographie.","question":"Quel intérêt est souligné ?","explanation":"Le passage indique : « Une commune conserve de petites mares malgré leur aspect parfois désordonné. Elles accueillent des espèces qui ne vivent pas dans les bassins décoratifs. » Cela justifie la réponse : La préservation d'habitats particuliers."},{"number":12,"points":15,"correct":"C","options":["Transformer les prairies en routes","Récolter le lait sans déplacement","Laisser les prairies se renouveler","Éviter toute alimentation des animaux"],"passage":"Un éleveur déplace ses animaux entre plusieurs parcelles. Les périodes de repos permettent à l'herbe de repousser.\n\nIl observe la végétation et les traces de passage avant de décider du prochain déplacement. L'exploitant ne présente pas la rotation comme un calendrier indépendant de la météo : elle demande un suivi, afin que l'organisation protège les ressources dont les animaux auront besoin pendant le reste de la saison.","question":"À quoi sert la rotation ?","explanation":"Le passage indique : « Un éleveur déplace ses animaux entre plusieurs parcelles. Les périodes de repos permettent à l'herbe de repousser. » Cela justifie la réponse : Laisser les prairies se renouveler."},{"number":13,"points":15,"correct":"B","options":["Le prix des clôtures","La présence de fleurs","La couleur des maisons","Le nombre de voitures"],"passage":"Des habitants relèvent la présence d'insectes sur une haie. Ils observent aussi les fleurs disponibles pour relier les visites aux ressources du lieu.\n\nLes bénévoles utilisent une fiche commune et choisissent plusieurs moments d'observation pour ne pas retenir seulement une visite exceptionnelle. Les espèces difficiles à identifier seront examinées avec une association. Le groupe souhaite apprendre à relier les présences aux conditions du lieu, sans conclure à partir d'une photographie isolée. Les habitants pourront ainsi comprendre pourquoi deux observations différentes ne signifient pas automatiquement qu'une plante attire toujours davantage d'insectes qu'une autre dans toutes les situations.","question":"Quelle information complète le comptage ?","explanation":"Le passage indique : « Des habitants relèvent la présence d'insectes sur une haie. Ils observent aussi les fleurs disponibles pour relier les visites aux ressources du lieu. » Cela justifie la réponse : La présence de fleurs."},{"number":14,"points":15,"correct":"D","options":["Supprimer toutes les ventes fraîches","Travailler uniquement un mois par an","Acheter exclusivement des produits importés","Réduire les variations saisonnières de revenus"],"passage":"Une ferme vend des produits transformés sur place pour mieux répartir ses revenus dans l'année. Les ateliers occupent notamment les périodes où les ventes fraîches diminuent.\n\nLes préparations sont choisies selon les produits disponibles et les équipements que la ferme peut utiliser correctement. Les clients peuvent acheter sur place ou lors de quelques marchés. L'exploitant suit le temps consacré à cette activité, car transformer demande aussi de nouvelles compétences et une organisation précise. Il ne suffit pas de conserver un produit pour garantir sa vente.","question":"Quel objectif économique est poursuivi ?","explanation":"Le passage indique : « Une ferme vend des produits transformés sur place pour mieux répartir ses revenus dans l'année. Les ateliers occupent notamment les périodes où les ventes fraîches diminuent. » Cela justifie la réponse : Réduire les variations saisonnières de revenus."},{"number":15,"points":15,"correct":"C","options":["Éviter toute observation","Appliquer une règle identique à toutes les graines","Distinguer les conditions de culture","Mesurer seulement le prix des sachets"],"passage":"Une classe découvre les semences avant le potager. Les élèves comparent leur taille et leurs besoins plutôt que planter tout au même moment.\n\nLes groupes peuvent comparer leurs observations avant d'intervenir. Les animateurs souhaitent éviter que l'activité soit réduite à enfouir des graines puis attendre un résultat identique. Certaines demandes d'eau, de lumière ou de température doivent être anticipées. À la fin de la saison, les élèves raconteront aussi les essais qui n'ont pas fonctionné, afin de comprendre ce qu'ils ont appris sans mesurer la réussite uniquement au nombre de légumes récoltés dans leur petite parcelle.","question":"Quel apprentissage est visé ?","explanation":"Le passage indique : « Une classe découvre les semences avant le potager. Les élèves comparent leur taille et leurs besoins plutôt que planter tout au même moment. » Cela justifie la réponse : Distinguer les conditions de culture."},{"number":16,"points":15,"correct":"C","options":["Remplacer les pierres par du plastique","Empêcher tous les passages d'eau","Conserver plusieurs fonctions du muret","Rendre le sol totalement étanche"],"passage":"Des bénévoles restaurent un muret sans ciment. Ils apprennent une technique locale qui permet l'écoulement de l'eau et offre des refuges à de petits animaux.\n\nLes participants observent les pierres disponibles avant de commencer et choisissent leur position avec l'aide d'un artisan. Ils ne cherchent pas à reproduire un décor sans comprendre sa construction. Le chantier permettra aussi de discuter des réparations anciennes et des gestes d'entretien. Le village souhaite conserver un savoir utile en donnant aux bénévoles l'occasion de pratiquer, plutôt qu'en montrant seulement un mur terminé.","question":"Quel avantage est indiqué ?","explanation":"Le passage indique : « Des bénévoles restaurent un muret sans ciment. Ils apprennent une technique locale qui permet l'écoulement de l'eau et offre des refuges à de petits animaux. » Cela justifie la réponse : Conserver plusieurs fonctions du muret."},{"number":17,"points":15,"correct":"B","options":["Récolter dans toutes les parcelles","Préserver les cultures pendant la récolte","Choisir gratuitement tout le stock","Entrer sans consigne"],"passage":"Un producteur ouvre une journée d'autocueillette. Les visiteurs paient les fruits récoltés et doivent respecter les rangs indiqués pour ne pas abîmer les plants.\n\nLes rangs ouverts sont marqués et les quantités pesées à la sortie. L'équipe explique quels fruits peuvent être cueillis et comment éviter de casser les branches. Les visiteurs sont invités à demander conseil plutôt qu'à déplacer les repères eux-mêmes. La ferme souhaite proposer une rencontre agréable avec la production, sans oublier que les plantes doivent continuer à donner après leur passage.","question":"Quelle responsabilité accompagne l'activité ?","explanation":"Le passage indique : « Un producteur ouvre une journée d'autocueillette. Les visiteurs paient les fruits récoltés et doivent respecter les rangs indiqués pour ne pas abîmer les plants. » Cela justifie la réponse : Préserver les cultures pendant la récolte."},{"number":18,"points":15,"correct":"D","options":["Une fermeture des commerces","Une hausse obligatoire des achats","Une suppression des relations de voisinage","Un accès plus autonome au marché"],"passage":"Un marché rural ajoute un arrêt de navette. Les personnes sans voiture peuvent désormais y venir, sans dépendre d'un voisin disponible.\n\nLes horaires ont été construits autour des jours de marché, avec un temps suffisant pour faire les achats sans courir. Une information sera distribuée aux habitants qui ne consultent pas les annonces en ligne. Les responsables regarderont si les correspondances et l'emplacement de l'arrêt conviennent réellement. Ils ne souhaitent pas présenter la création de la ligne comme une réponse achevée avant de connaître l'expérience des premiers usagers.","question":"Quel effet est attendu ?","explanation":"Le passage indique : « Un marché rural ajoute un arrêt de navette. Les personnes sans voiture peuvent désormais y venir, sans dépendre d'un voisin disponible. » Cela justifie la réponse : Un accès plus autonome au marché."},{"number":19,"points":15,"correct":"C","options":["Refuser toute comparaison annuelle","Ignorer les dates de floraison","Croiser les observations avant de conclure","Considérer un seul événement comme suffisant"],"passage":"Une association surveille les floraisons chaque année. Une floraison plus précoce sera interprétée avec d'autres observations, pas comme la preuve isolée d'une tendance générale.\n\nLe groupe utilise plusieurs points fixes et conserve les relevés même lorsqu'aucun changement remarquable n'est visible. Les participants peuvent noter les conditions du moment et demander une vérification de leur identification. L'association souhaite construire une série utile, pas seulement recueillir des annonces de phénomènes inhabituels. Les visiteurs découvriront les résultats avec ces limites.","question":"Quelle prudence est exprimée ?","explanation":"Le passage indique : « Une association surveille les floraisons chaque année. Une floraison plus précoce sera interprétée avec d'autres observations, pas comme la preuve isolée d'une tendance générale. » Cela justifie la réponse : Croiser les observations avant de conclure."},{"number":20,"points":21,"correct":"A","options":["Donner de la stabilité avec un suivi","Exiger des résultats immédiats identiques","Réserver les terres aux exploitants déjà installés","Offrir un accès sans aucune règle"],"passage":"Une commune loue des terres à de nouveaux agriculteurs. Le bail laisse du temps pour développer une activité, mais prévoit un suivi des pratiques et des engagements pris. Les candidats présentent leur projet et les moyens dont ils disposent pour le mettre en place. Le service souhaite leur donner le temps d'apprendre le terrain et de préparer leurs débouchés. Les rencontres de suivi permettront d'identifier les difficultés, sans modifier les règles à chaque imprévu. La commune veut une activité viable et cohérente avec les objectifs annoncés, plutôt qu'une installation rapide qui disparaîtrait après une première saison difficile.","question":"Quel équilibre est recherché ?","explanation":"Le passage indique : « Une commune loue des terres à de nouveaux agriculteurs. Le bail laisse du temps pour développer une activité, mais prévoit un suivi des pratiques et des engagements pris. » Cela justifie la réponse : Donner de la stabilité avec un suivi."},{"number":21,"points":21,"correct":"A","options":["Plusieurs changements ont eu lieu simultanément","Les habitants ignorent le lieu de la ferme","Les mesures n'ont jamais été réalisées","Aucun oiseau n'a été observé"],"passage":"Le retour de certains oiseaux près d'une ferme encourage ses habitants. Ils ne l'attribuent pas à une seule mesure : haies, mares et changements de pratiques ont été mis en place ensemble. Les habitants ont participé à plusieurs actions et les changements ne peuvent pas être isolés facilement dans leurs souvenirs. Une association propose de garder des repères communs pour les prochaines années. Les observations resteront utiles, même sans permettre d'affirmer qu'un geste unique explique tout.","question":"Pourquoi rester prudent sur la cause ?","explanation":"Le passage indique : « Le retour de certains oiseaux près d'une ferme encourage ses habitants. Ils ne l'attribuent pas à une seule mesure : haies, mares et changements de pratiques ont été mis en place ensemble. » Cela justifie la réponse : Plusieurs changements ont eu lieu simultanément."},{"number":22,"points":21,"correct":"A","options":["Préserver tout en adaptant à un nouvel usage","Conserver uniquement le nom de la ferme","Reconstruire une copie sans utiliser le bâtiment","Interdire toute activité nouvelle"],"passage":"Un village transforme un ancien bâtiment agricole en atelier partagé. Il conserve la charpente, mais adapte l'accès aux normes actuelles. La conservation ne signifie pas l'absence de modification. Les futurs utilisateurs ont expliqué les espaces nécessaires au rangement, aux machines et à la circulation. Certains éléments seront protégés ou déplacés pour permettre ces activités. Le comité souhaite que les visiteurs puissent encore comprendre l'histoire du bâtiment. Il refuse cependant de confondre respect du lieu et impossibilité d'y travailler autrement.","question":"Quelle démarche est décrite ?","explanation":"Le passage indique : « Un village transforme un ancien bâtiment agricole en atelier partagé. Il conserve la charpente, mais adapte l'accès aux normes actuelles. La conservation ne signifie pas l'absence de modification. » Cela justifie la réponse : Préserver tout en adaptant à un nouvel usage."},{"number":23,"points":21,"correct":"B","options":["Une disparition des responsabilités","Une coordination entre producteurs","L'arrêt de toute production","L'obligation de vendre les mêmes produits"],"passage":"Des agriculteurs proposent une vente collective. Chacun gagne du temps de commercialisation, mais doit accepter des règles communes de présence et de présentation des produits. Les produits de chacun sont identifiés et les ventes suivies dans un document partagé. Les décisions importantes seront discutées avant d'être appliquées. Les agriculteurs veulent que la boutique reste compatible avec leurs périodes de travail sur les terres. Ils devront parfois échanger une permanence ou réduire une présence annoncée.","question":"Quelle contrepartie accompagne le gain de temps ?","explanation":"Le passage indique : « Des agriculteurs proposent une vente collective. Chacun gagne du temps de commercialisation, mais doit accepter des règles communes de présence et de présentation des produits. » Cela justifie la réponse : Une coordination entre producteurs."},{"number":24,"points":21,"correct":"D","options":["Remplacer les fermes par des cartes postales","Ignorer toute intervention humaine","Évaluer uniquement les couleurs","Comprendre les activités qui le façonnent"],"passage":"Un parcours explique les paysages avec les témoignages de travailleurs agricoles. Les champs sont présentés comme des espaces de production et de décisions, pas seulement comme un décor. Les témoins racontent les rythmes de l'année et les raisons de certaines transformations visibles depuis le chemin. Les visiteurs pourront comparer ces récits avec des cartes. Les organisateurs ne demandent pas aux habitants de présenter une campagne idéale ni de justifier chaque choix devant le public.","question":"Quelle lecture du paysage est proposée ?","explanation":"Le passage indique : « Un parcours explique les paysages avec les témoignages de travailleurs agricoles. Les champs sont présentés comme des espaces de production et de décisions, pas seulement comme un décor. » Cela justifie la réponse : Comprendre les activités qui le façonnent."},{"number":25,"points":21,"correct":"D","options":["La moyenne de places libres permet de comparer les capacités lorsque les périodes de pointe concernent les mêmes cultures.","Les semaines où l'entrepôt est presque vide permettent de renoncer à l'agrandissement sans examiner les récoltes.","Des pointes simultanées rendent le partage impossible même si certains volumes peuvent être décalés entre les sites.","Parce qu'une capacité inutilisée sur l'année peut masquer des pointes simultanées où aucun espace n'est disponible."],"passage":"Une coopérative hésite entre agrandir son entrepôt et mieux partager les capacités existantes. Elle réalise d'abord un état des lieux des périodes d'utilisation avant d'investir. Le groupe relève les volumes, les moments de pointe et les marges disponibles dans les bâtiments voisins. Certains espaces semblent vides une partie de l'année, mais leur usage reste important pendant une courte période. La coopérative veut donc regarder l'ensemble du calendrier avant de conclure à une capacité inutile ou insuffisante. Le relevé montre que deux entrepôts ont chacun 30 % de places libres en moyenne, mais qu'ils atteignent leur capacité maximale pendant les mêmes trois semaines de récolte. La coopérative examine si les volumes peuvent être décalés avant de conclure que ces places suffisent.","question":"Pourquoi un taux moyen d'occupation ne permet-il pas à lui seul de décider l'investissement ?","explanation":"D est appuyé par les deux entrepôts simultanément saturés durant trois semaines malgré une moyenne de places libres de 30 %. A attribue aux moyennes une comparabilité suffisante; B ignore la saison des récoltes; C conclut trop vite à l'impossibilité de tout décalage."},{"number":26,"points":21,"correct":"A","options":["Une organisation des soins et des relais doit prolonger l'enthousiasme et les gestes initiaux.","Les tâches d'entretien peuvent être fixées sans tenir compte des absences prévues.","La présence d'un premier jardinier suffira dès lors que les plants ont survécu à leur première saison.","Le nombre de fruits récoltés l'année de plantation permet d'éviter toute répartition ultérieure des tâches."],"passage":"Des habitants veulent planter des arbres fruitiers communs. L'association prévoit aussi qui taillera, arrosera et récoltera. La plantation n'est que le début de l'engagement. Les habitants préparent un calendrier et identifient les personnes pouvant transmettre les gestes nécessaires aux nouveaux participants. Des périodes d'absence doivent aussi être prévues. Le projet ne veut pas dépendre d'un seul jardinier enthousiaste qui s'occuperait de tout sans relais. Les décisions porteront donc sur les plantations et sur les conditions qui permettront de les garder en bon état. Les premières plantations ont bien repris, mais les arbres taillés par une seule personne ont été négligés durant ses vacances. Le groupe répartit désormais les savoir-faire et les remplacements dans un calendrier accessible.","question":"Quelle condition distingue la réussite initiale d'une plantation de sa pérennité ?","explanation":"La plantation n'est qu'un début; les relais et l'entretien assurent la durée. A. Les autres ignorent les absences et soins."},{"number":27,"points":21,"correct":"D","options":["La sécheresse d'août indique le fonctionnement ordinaire du site puisque les épisodes de rétention printaniers sont temporaires.","Le nombre d'espèces recensées en août reflète le fonctionnement annuel, à condition de tenir compte des pluies antérieures.","Une zone sans eau visible ne peut avoir un rôle de rétention que si les mêmes plantes restent en surface.","Elle donne un état ponctuel qui ne permet pas de juger les fonctions saisonnières de la zone."],"passage":"Une zone humide est parfois vide d'eau en été. Des visiteurs la jugent inutile, mais les gestionnaires expliquent que ses cycles saisonniers font partie de son fonctionnement. Les gestionnaires montreront des photographies prises à différents moments et expliqueront les espèces qui utilisent le lieu. Certaines fonctions sont moins faciles à observer pendant une visite courte. Le programme souhaite donner ces repères sans prétendre qu'un état unique serait le bon toute l'année. En été sec, certaines plantes ont disparu en surface; les observations de printemps montrent pourtant que la zone retient temporairement l'eau et accueille d'autres espèces. Le guide demande d'interpréter le lieu sur plusieurs saisons.","question":"Pourquoi l'observation d'une parcelle sèche en août serait-elle insuffisante ?","explanation":"D rappelle qu'un état sec en août ne représente pas les fonctions saisonnières observées au printemps. A et B étendent abusivement la visite estivale à toute l'année; C conditionne la fonction de rétention aux seules plantes visibles."},{"number":28,"points":21,"correct":"B","options":["Écarter toute production rentable pour éliminer définitivement les incertitudes de vente.","Répartir l'exposition économique entre plusieurs activités malgré un coût initial d'adaptation.","Maximiser le rendement immédiat des nouvelles cultures avant d'évaluer leurs débouchés.","Remplacer une dépendance à un acheteur par une dépendance encore plus forte à un seul marché."],"passage":"Un agriculteur réduit une culture très rentable pour diversifier ses productions. Il accepte un gain immédiat moins élevé afin de moins dépendre d'un seul débouché. Il étudie d'autres ventes possibles et réserve du temps pour apprendre les nouvelles cultures. Cette évolution comporte elle aussi des difficultés, qu'il ne veut pas cacher dans son bilan. L'exploitant cherche une organisation moins fragile lorsqu'un prix baisse ou qu'un acheteur se retire. Le prix de sa culture principale avait fortement chuté alors que les deux autres débouchés restaient stables. L'agriculteur accepte les coûts d'apprentissage de nouvelles cultures pour diminuer la part de revenu liée à ce seul marché.","question":"Quel raisonnement justifie l'abandon d'une part de rentabilité à court terme ?","explanation":"La diversification sert à réduire le risque de concentration. B. C/D/A contredisent la logique ou promettent une sécurité absolue."},{"number":29,"points":21,"correct":"D","options":["Une succession d'activités nouvelles indépendantes des traditions déjà pratiquées dans le village.","Un calendrier nouveau qui efface les activités héritées pour faciliter l'arrivée de bénévoles.","Une fête réservée aux personnes connaissant les usages, avec une consultation organisée après l'événement.","Une tradition conservée tout en accueillant des contributions venues de nouveaux habitants du village."],"passage":"Une fête de village donne une place aux nouveaux habitants dans son organisation. Les traditions restent présentes, mais des activités supplémentaires sont proposées après discussion. Les nouveaux bénévoles peuvent participer aux réunions et proposer un rôle correspondant à leurs disponibilités. Les organisateurs souhaitent transmettre les habitudes sans demander de les connaître toutes avant de venir. Le programme final garde des repères familiers et introduit quelques essais. Une activité ancienne est maintenue, mais le parcours de la fête est modifié à la suggestion de nouveaux arrivants pour inclure des habitants jusque-là peu présents. Les anciens bénévoles expliquent les repères historiques sans imposer de les connaître.","question":"Quelle forme de continuité le nouveau programme cherche-t-il à construire ?","explanation":"Le projet maintient des éléments et accepte des modifications discutées. D. B/C/A suppriment cette articulation."},{"number":30,"points":26,"correct":"C","options":["Parce que toutes les campagnes sont désormais définies principalement par leur distance à la ville.","Parce que le monde rural ne subit plus aucun changement depuis l'arrivée des nouveaux métiers.","Parce que services et relations urbaines créent des besoins différents selon les villages.","Parce que la présence d'agriculture empêche d'analyser les autres formes d'activité."],"passage":"L'image d'une campagne immobile masque les transformations des métiers, des techniques et des relations entre habitants. Un chercheur observe ces changements sans en déduire que tous les villages suivent la même trajectoire. La ruralité ne décrit pas une situation unique. Il compare notamment l'accès aux services, les activités et les relations avec les villes proches. Ces éléments aident à comprendre pourquoi une mesure utile dans un village ne produit pas automatiquement le même effet dans tous les autres. Deux villages voisins connaissent des trajectoires opposées: l'un accueille des télétravailleurs grâce au train, l'autre perd une ligne de bus et des services. Une aide identique ne leur donnerait pas les mêmes possibilités.","question":"Pourquoi le chercheur refuse-t-il une mesure rurale universelle ?","explanation":"Les territoires connaissent des changements non uniformes. C; B/A/D simplifient précisément ce que l'enquête distingue."},{"number":31,"points":26,"correct":"C","options":["Elle pénalise les sites qui photographient davantage les opérations de plantation.","Elle tient trop compte du besoin d'arrosage et pas assez du nombre de personnes présentes.","Elle confond l'action initiale financée avec la persistance réelle de ses résultats au fil des saisons.","Elle suppose que des pertes constatées deux ans plus tard prouvent la mauvaise qualité de chaque plant."],"passage":"Une aide agricole dépend du nombre d'arbres plantés. Certains bénéficiaires demandent qu'un suivi de leur survie soit également financé. Compter les plantations sans regarder leur avenir risque de récompenser un geste ponctuel plutôt qu'un effet durable sur le paysage. Elles demandent des moyens pour agir après la photographie du jour de plantation, lorsque la réussite dépend encore de gestes moins visibles mais réguliers. Sur cent jeunes arbres photographiés le jour de la plantation, soixante restent vivants deux ans après dans une commune et quatre-vingt-dix dans l'autre. Le nombre initial identique ne mesure pas l'effet durable recherché.","question":"Quelle limite présente une aide indexée seulement sur le nombre d'arbres mis en terre ?","explanation":"La survie diffère malgré des plantations identiques. C distingue activité et effet; les autres attribuent des causes non établies."},{"number":32,"points":26,"correct":"A","options":["L'origine effective des produits et l'organisation de leur acheminement, indépendamment du nombre d'intermédiaires.","Le rythme des livraisons donne une estimation de la distance réelle parcourue.","Le nombre de clients servis reflète les volumes expédiés et permet donc de comparer l'importance des distances de livraison.","La part des ventes directes indique le circuit le plus court et permet d'estimer les kilomètres parcourus par chaque panier."],"passage":"Un circuit court réduit le nombre d'intermédiaires, mais ne dit pas à lui seul quelle distance parcourt le produit. Un achat direct très éloigné peut demander davantage de transport qu'un produit distribué localement par plusieurs acteurs. Les consommateurs peuvent donc demander où le produit a été fabriqué et comment il est acheminé. Une information claire permettra de comparer les offres sans attribuer à un seul terme des garanties qu'il ne donne pas forcément. Un producteur livre directement ses paniers à 300 kilomètres, tandis qu'un grossiste distribue des pommes provenant de fermes à 20 kilomètres. Le nombre d'acteurs et la distance évoluent donc séparément.","question":"Quel indicateur faudrait-il ajouter à la mention « circuit court » pour comparer les deux offres ?","explanation":"A demande l'origine et l'acheminement réel, que ne décrit pas le seul nombre d'intermédiaires. B substitue fréquence à distance, C déduit les kilomètres du nombre de clients et D confond vente directe et proximité géographique."},{"number":33,"points":26,"correct":"B","options":["Ils conservent toujours la mesure numérique, les signes du terrain étant purement subjectifs.","Ils confrontent les données du capteur aux observations locales avant de choisir l'arrosage.","Ils suivent l'observation traditionnelle sans examiner la profondeur à laquelle la sonde mesure.","Ils additionnent mécaniquement les deux indications, même si elles concernent des lieux distincts."],"passage":"Des pratiques agricoles se transmettent par l'observation de signes locaux : état du sol, végétation, humidité. Un nouvel outil apporte d'autres données. Les utilisateurs les plus expérimentés ne choisissent pas forcément entre les deux ; ils cherchent comment les confronter utilement. Les producteurs discutent les cas où les deux sources se complètent et ceux où elles semblent se contredire. Une sonde indique un sol encore humide, mais un agriculteur observe une croûte superficielle sur une parcelle voisine. Le groupe vérifie la profondeur et la localisation des mesures avant de choisir l'arrosage.","question":"Comment les producteurs traitent-ils des indications apparemment divergentes ?","explanation":"Le croisement exige de comprendre contexte et limites des sources. B; les autres privilégient ou combinent les indications sans contrôle."},{"number":34,"points":26,"correct":"B","options":["Réserver les heures fréquentées aux visiteurs et reporter les passages agricoles.","Une cohabitation organisée selon les périodes et les contraintes des usages déjà présents.","Maintenir les chemins accessibles aux visiteurs pendant la journée, les agriculteurs devant adapter leurs horaires aux promenades.","Donner la priorité aux engins durant la récolte, en laissant les visiteurs adapter seuls leurs passages sans calendrier partagé."],"passage":"Une commune aménage des chemins pour les visiteurs, mais les engins agricoles doivent continuer à circuler. Les règles élaborées avec les usagers tiennent compte des périodes de travail. Ouvrir un espace ne signifie pas effacer les activités qui y existaient déjà. Le projet veut rendre les rencontres possibles tout en expliquant pourquoi certaines contraintes ne peuvent pas être décidées uniquement selon le confort des visiteurs. La promenade est très fréquentée en juillet, période où les engins ont aussi besoin d'un passage large pour la récolte. Le comité propose des horaires de circulation affichés plutôt qu'un accès permanent privilégiant une seule activité.","question":"Quel arbitrage les règles d'accès cherchent-elles à rendre possible ?","explanation":"B organise une cohabitation discutée selon les périodes de travail. A et C font passer les promenades avant les besoins agricoles; D inverse la priorité sans proposer la coordination et l'information prévues."},{"number":35,"points":26,"correct":"A","options":["Elle relie les gestes observés aux décisions et aux contraintes qui expliquent la production réelle.","Elle permet aux élèves de comparer les méthodes de travail sans examiner leurs effets sur la production.","Elle rend les visites plus authentiques en montrant exclusivement les imprévus au lieu des pratiques ordinaires.","Elle confirme que les gestes observés ont des conséquences constantes indépendamment des conditions de travail."],"passage":"Des fermes accueillent des classes pour montrer la production alimentaire. Les visites les plus riches ne se limitent pas à une démonstration agréable : elles expliquent aussi les choix difficiles et les incertitudes du métier. Comprendre une activité demande parfois de dépasser son image rassurante. Les responsables souhaitent qu'ils comprennent les liens entre une décision et ses conséquences, au lieu de repartir avec une image agréable mais incomplète d'une journée de travail. Une classe assiste à la traite puis découvre pourquoi la ferme adapte ses pratiques en période de sécheresse. Les élèves posent des questions sur les choix et leurs conséquences au lieu de ne retenir que la démonstration.","question":"Pourquoi la présentation des difficultés professionnelles approfondit-elle la visite ?","explanation":"A relie gestes, choix et contraintes. B sépare artificiellement décisions et conséquences; C remplace une présentation partielle par une autre; D efface les aléas que l'équipe veut faire comprendre."},{"number":36,"points":33,"correct":"A","options":["Préserver des qualités paysagères tout en adaptant certains usages du territoire, pour les besoins actuels des habitants.","La conservation des formes bâties est prioritaire lorsque les usages anciens restent économiquement viables.","Les adaptations contemporaines doivent être déterminées surtout par les besoins immédiats sans relever les traces du passé.","Une rénovation préserve l'aspect d'un lieu seulement si son usage actuel demeure identique à l'ancien."],"passage":"Un projet propose de protéger un paysage en interdisant toute transformation. Les habitants rappellent que ce paysage résulte lui-même de pratiques successives. Ils souhaitent préserver des qualités sans figer les conditions de vie. La conservation d'un territoire habité doit composer avec les besoins de ceux qui continuent à le faire vivre. Certains bâtiments nécessitent de nouvelles fonctions pour rester entretenus, et les exploitants doivent parfois changer leur organisation. Les habitants souhaitent distinguer ces besoins de transformations qui effaceraient sans raison les qualités du lieu. La discussion devra donc examiner des cas concrets et leurs effets. Une règle générale apparemment protectrice peut devenir difficile à vivre si elle traite toute modification comme une dégradation. Les responsables du projet proposent des visites communes pour comprendre les usages présents, les héritages à maintenir et les possibilités d'adaptation compatibles avec la vie du village. Une ancienne grange, remarquable dans le paysage, risque de tomber en ruine sans nouvelle utilisation. Les habitants proposent de conserver son volume extérieur tout en y installant une activité compatible avec les besoins actuels.","question":"Quelle conception de la protection patrimoniale sous-tend cette proposition ?","explanation":"A propose de conserver des qualités tout en adaptant certains usages. B subordonne la préservation à la rentabilité, ce que le cas n'énonce pas; C néglige le patrimoine; D impose un maintien des fonctions refusé par le projet."},{"number":37,"points":33,"correct":"D","options":["Il remplacerait une mesure de production par une mesure de surface, sans inclure les services rendus au territoire.","Il donnerait une image des revenus agricoles mais laisserait inconnues les quantités réellement commercialisées.","Il montrerait une différence de rendement que la contribution des haies suffirait à annuler.","Il négligerait des contributions environnementales et collectives qui ne se reflètent pas directement dans le rendement."],"passage":"Une exploitation est souvent évaluée par son rendement sur une seule culture. Pourtant, elle entretient aussi des haies, partage du matériel et contribue à l'emploi local. Ces fonctions ne justifient pas d'ignorer le rendement, mais elles élargissent les questions à poser. Une performance devient différente selon les dimensions que l'on accepte de compter. Les responsables souhaitent notamment rendre visibles des tâches qui n'apparaissent pas directement dans les volumes vendus. Les comparaisons devront donc préciser ce qu'elles retiennent et les limites du résultat. Une ferme peut présenter des forces et des difficultés différentes selon le domaine observé. Le bilan devient plus utile lorsqu'il aide à discuter ces écarts, plutôt que lorsqu'il transforme un seul chiffre en classement complet de toutes les activités et de leurs effets sur le territoire. Une ferme vend moins de tonnes que sa voisine mais entretient des haies et partage des équipements avec plusieurs exploitations. Le bilan sépare donc production, contribution environnementale et services au territoire.","question":"Pourquoi un classement fondé sur le seul volume vendu serait-il incomplet ?","explanation":"D indique les fonctions écologiques et collectives absentes du seul volume vendu. A reste un indicateur partiel; B confond tonnes et revenus; C suppose une compensation non chiffrée."},{"number":38,"points":33,"correct":"D","options":["Les tâches de distribution deviennent secondaires lorsque les clients passent directement leurs commandes au producteur.","Le lien direct devient plus rentable quand les fonctions commerciales sont confiées exclusivement à chaque exploitation.","Le nombre d'intermédiaires révèle mieux la charge de travail que le temps consacré aux commandes et aux retraits.","Les fonctions demeurent et doivent être assumées ou réparties, même si le circuit commercial change."],"passage":"La vente directe est parfois présentée comme une relation spontanée entre producteur et consommateur. Elle demande pourtant du temps pour accueillir, expliquer et organiser les commandes. Un producteur peut bien cultiver sans souhaiter assurer seul cette activité supplémentaire. Réduire les intermédiaires ne fait pas disparaître les fonctions qu'ils prenaient en charge. Les clients doivent pouvoir connaître les horaires, réserver, obtenir une réponse et récupérer leur commande dans de bonnes conditions. Ces tâches peuvent être partagées ou confiées à un partenaire sans effacer le lien recherché avec les producteurs. Le débat ne porte donc pas seulement sur le nombre d'acteurs entre le champ et le panier. Il concerne aussi la manière dont le travail est réparti et reconnu. Les exploitants souhaitent comparer les solutions avec leur charge réelle, afin qu'une formule présentée comme plus simple pour l'acheteur ne rende pas leur propre activité plus difficile à maintenir. Un producteur augmente ses ventes directes mais passe chaque semaine davantage d'heures à répondre aux messages et à coordonner les retraits. Une solution collective lui permettrait de déléguer ces tâches sans ajouter un intermédiaire inutile au sens du projet.","question":"Que signifie la réduction du nombre d'intermédiaires pour l'organisation du travail ?","explanation":"D rappelle que la suppression d'intermédiaires n'efface pas les fonctions commerciales. A minimise les tâches, B impose leur prise en charge individuelle, C confond structure du circuit et charge effective."},{"number":39,"points":33,"correct":"B","options":["La progression du nombre total de ménages atteste que l'objectif de maintien est atteint, même si les parcours résidentiels individuels ne sont pas suivis.","Le léger gain global doit être rapproché des départs de familles installées et des difficultés de logement, sans prétendre attribuer chaque départ au programme.","Les commerces mieux fréquentés suffisent à apprécier indirectement si les anciens habitants peuvent financer leur logement.","La hausse des déplacements professionnels permet d'attribuer tous les départs des familles aux loyers plus élevés."],"passage":"Un village développe son attractivité pour retenir des habitants. Des services nouveaux apparaissent, mais le prix des logements augmente. Les familles que le projet voulait initialement maintenir peuvent alors rencontrer davantage de difficultés. L'attractivité n'est pas automatiquement synonyme d'accessibilité pour les habitants déjà présents. Les élus doivent donc suivre les coûts du logement en même temps que les arrivées et les recettes nouvelles. Les habitants demandent des possibilités de rester près de leur travail et de leurs proches. Plusieurs solutions seront étudiées, dont des logements accessibles et un maintien de certains services ordinaires. Le programme ne sera pas jugé uniquement à partir d'une image plus attractive ou d'une hausse des visites. Il faudra aussi regarder qui peut encore vivre sur place et dans quelles conditions, afin de comprendre à qui profite réellement le changement annoncé pour l'ensemble du village. Le nouveau café attire des visiteurs et des ménages aisés, mais une famille du village doit quitter son logement après une forte hausse de loyer. Le conseil suit désormais les prix et les départs autant que l'ouverture de services. Pour dresser son bilan, le conseil distingue désormais les nouvelles inscriptions à l'école, les départs de familles déjà installées et les changements de propriétaires. Sur deux ans, le nombre total de ménages augmente légèrement, mais six familles présentes avant le programme sont parties après une hausse de loyer. Trois logements quittés sont occupés par de nouveaux ménages. Le café et les commerces ont gagné des clients, tandis que les salariés aux revenus modestes parcourent en moyenne davantage de kilomètres pour rejoindre leur emploi dans le village. Les élus notent que les dossiers de départ ne permettent pas tous de prouver que le loyer est l'unique motif; certains mentionnent aussi des mutations professionnelles. Le tableau présenté au public sépare donc le solde global de population, la stabilité des habitants antérieurs et les conditions de logement. Les promoteurs du projet souhaitent publier seulement la progression du nombre de ménages, que les associations locales jugent insuffisante.","question":"Quel bilan permet d'apprécier le maintien des habitants sans confondre hausse globale et stabilité des résidents antérieurs ?","explanation":"B distingue une légère hausse du nombre total de ménages du départ de familles déjà présentes et garde une réserve sur les causes. A assimile remplacement et maintien; C infère la capacité résidentielle des recettes commerciales; D attribue tous les départs aux loyers malgré des motifs multiples."}]}$paper_12$::jsonb),
('tcf-reading-13','tcf-reading-2026-11-distractor-polish-v5',$paper_13${"id":"tcf-reading-13","title":"TCF Reading · Test 13","seconds":3600,"version":"tcf-reading-2026-11-distractor-polish-v5","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"A","options":["L'impression à l'accueil","L'accès à tous les ordinateurs","Le cours dans la salle fermée","Le prêt d'une imprimante personnelle"],"passage":"La salle informatique sera fermée pour mise à jour mardi matin. L'accueil pourra toujours imprimer vos documents.\n\nLes agents retrouveront le service habituel après les vérifications. Merci de ne pas essayer d'entrer dans la salle pendant l'intervention.","question":"Quel service sera maintenu ?","explanation":"Le passage indique : « La salle informatique sera fermée pour mise à jour mardi matin. L'accueil pourra toujours imprimer vos documents. » Cela justifie la réponse : L'impression à l'accueil."},{"number":2,"points":3,"correct":"B","options":["Publier ses identifiants","Joindre l'assistance par son canal connu","Donner son mot de passe","Rappeler le numéro fourni sans vérification"],"passage":"Votre mot de passe ne vous sera jamais demandé par téléphone. En cas d'appel suspect, contactez directement l'assistance habituelle.\n\nLe numéro figure sur vos documents de service.","question":"Que faut-il faire après un appel suspect ?","explanation":"Le passage indique : « Votre mot de passe ne vous sera jamais demandé par téléphone. En cas d'appel suspect, contactez directement l'assistance habituelle. » Cela justifie la réponse : Joindre l'assistance par son canal connu."},{"number":3,"points":3,"correct":"C","options":["Supprimer la batterie","Acheter un nouveau téléphone","Recharger l'appareil","Imprimer toutes les photos"],"passage":"L'atelier photo accepte les téléphones anciens. Chargez votre batterie avant de venir ; les prises disponibles sont limitées.\n\nLes participants pourront venir avec un modèle qu'ils utilisent déjà au quotidien, sans devoir en acheter un autre.","question":"Quelle préparation est demandée ?","explanation":"Le passage indique : « L'atelier photo accepte les téléphones anciens. Chargez votre batterie avant de venir ; les prises disponibles sont limitées. » Cela justifie la réponse : Recharger l'appareil."},{"number":4,"points":3,"correct":"A","options":["Envoyer","Enregistrer provisoirement","Agrandir le texte","Fermer la fenêtre"],"passage":"Le formulaire peut être enregistré puis repris plus tard. Le bouton « Envoyer » termine la démarche.\n\nUn message confirme ensuite la réception. Avant cette dernière étape, vous pouvez encore relire et corriger les informations saisies dans votre dossier personnel.","question":"Quel bouton finalise le dossier ?","explanation":"Le passage indique : « Le formulaire peut être enregistré puis repris plus tard. Le bouton « Envoyer » termine la démarche. » Cela justifie la réponse : Envoyer."},{"number":5,"points":9,"correct":"D","options":["Empêcher toute modification","Réduire le nombre de participants","Remplacer les fichiers par des appels","Limiter la confusion entre les versions"],"passage":"Je t'enverrai les fichiers par le dossier partagé. Évite les pièces jointes : nous risquerions de travailler sur des versions différentes.\n\nJ'ai préparé des noms de documents simples pour retrouver rapidement le travail de chacun. Nous pourrons discuter des modifications dans la note commune sans multiplier les copies.","question":"Pourquoi utiliser un dossier commun ?","explanation":"Le passage indique : « Je t'enverrai les fichiers par le dossier partagé. Évite les pièces jointes : nous risquerions de travailler sur des versions différentes. » Cela justifie la réponse : Limiter la confusion entre les versions."},{"number":6,"points":9,"correct":"B","options":["Le partage de tous les mots de passe","La non-conservation des codes par l'accompagnateur","L'envoi des codes aux autres participants","La publication des comptes créés"],"passage":"La permanence numérique accompagne les démarches, mais ne conserve pas vos codes. Vous devrez les saisir vous-même.\n\nLe bénévole peut expliquer où trouver une information, mais les données restent sous votre responsabilité. Merci de fermer votre session après la démarche.","question":"Quelle règle protège l'utilisateur ?","explanation":"Le passage indique : « La permanence numérique accompagne les démarches, mais ne conserve pas vos codes. Vous devrez les saisir vous-même. » Cela justifie la réponse : La non-conservation des codes par l'accompagnateur."},{"number":7,"points":9,"correct":"B","options":["Abandonner tout appel","Prolonger l'usage du téléphone","Vendre la batterie neuve","Acheter immédiatement un modèle récent"],"passage":"Mon téléphone fonctionne encore. Je préfère changer sa batterie plutôt que remplacer tout l'appareil.\n\nLe réparateur a vérifié que cette intervention est possible sur mon modèle. Je conserverai aussi mes photos avant de lui laisser l'appareil, par précaution. Je demanderai aussi combien de temps cela prendra.","question":"Quelle décision est prise ?","explanation":"Le passage indique : « Mon téléphone fonctionne encore. Je préfère changer sa batterie plutôt que remplacer tout l'appareil. » Cela justifie la réponse : Prolonger l'usage du téléphone."},{"number":8,"points":9,"correct":"D","options":["Un nouvel ordinateur gratuit","Un examen en salle obligatoire","Une vidéo sans son uniquement","Un texte de la séance"],"passage":"Pour suivre le cours à distance, un casque est conseillé, pas obligatoire. Une transcription écrite sera disponible après la séance.\n\nLes personnes souhaitant revoir un passage pourront le retrouver après la rencontre.","question":"Quel autre support est prévu ?","explanation":"Le passage indique : « Pour suivre le cours à distance, un casque est conseillé, pas obligatoire. Une transcription écrite sera disponible après la séance. » Cela justifie la réponse : Un texte de la séance."},{"number":9,"points":9,"correct":"B","options":["Travailler uniquement la nuit","Mieux maîtriser les interruptions","Supprimer définitivement sa messagerie","Empêcher tous ses proches d'écrire"],"passage":"J'ai désactivé les notifications pendant mes révisions. Je regarderai les messages à des moments choisis.\n\nJe répondrai aux demandes importantes après ma séance de travail. Si une urgence se présente, mes proches savent comment me joindre autrement que par une succession de notifications.","question":"Quel objectif poursuit cette personne ?","explanation":"Le passage indique : « J'ai désactivé les notifications pendant mes révisions. Je regarderai les messages à des moments choisis. » Cela justifie la réponse : Mieux maîtriser les interruptions."},{"number":10,"points":9,"correct":"B","options":["Un appareil acheté neuf","La tablette et son chargeur","Uniquement la housse","Un abonnement téléphonique"],"passage":"Le club prête des tablettes pour le week-end. Elles doivent être rapportées lundi avec leur chargeur.\n\nUne fiche indiquera les précautions et les accessoires remis au départ. Les emprunteurs devront signaler un problème avant de repartir avec le matériel pour un nouveau prêt.","question":"Que faut-il restituer ?","explanation":"Le passage indique : « Le club prête des tablettes pour le week-end. Elles doivent être rapportées lundi avec leur chargeur. » Cela justifie la réponse : La tablette et son chargeur."},{"number":11,"points":15,"correct":"D","options":["Acheter du stockage supplémentaire","Effacer tous les dossiers","Créer des programmes complexes","Acquérir un repère de base"],"passage":"Une association propose une initiation au rangement des fichiers. Les participants apprennent d'abord à retrouver un document avant d'utiliser des fonctions plus avancées.\n\nLe formateur utilise des exemples courants et laisse les personnes choisir un classement qu'elles comprennent. Il montre aussi comment éviter des noms trop semblables et comment reconnaître plusieurs versions d'un même fichier. Les participants essaient ensuite de retrouver un document après avoir fermé le dossier. L'objectif est de vérifier qu'ils possèdent un repère utilisable seuls, pas seulement qu'ils réussissent à suivre une démonstration. Les questions permettront de préparer les séances suivantes selon les usages réellement rencontrés dans leur quotidien personnel ou professionnel.","question":"Quelle priorité est donnée ?","explanation":"Le passage indique : « Une association propose une initiation au rangement des fichiers. Les participants apprennent d'abord à retrouver un document avant d'utiliser des fonctions plus avancées. » Cela justifie la réponse : Acquérir un repère de base."},{"number":12,"points":15,"correct":"A","options":["Si l'accès demandé correspond au service","Si tous les contacts utilisent l'application","Si le logo est suffisamment coloré","Si le téléphone est assez grand"],"passage":"Une application demande l'accès aux contacts pour afficher la météo. Une animatrice explique que cette autorisation n'est pas nécessaire à la fonction annoncée.\n\nLes participants comparent plusieurs exemples pour éviter de penser qu'une application doit toujours recevoir tous les accès proposés. Le but n'est pas de refuser automatiquement chaque service, mais de comprendre la relation entre une fonction et les informations demandées.","question":"Quelle question faut-il se poser ?","explanation":"Le passage indique : « Une application demande l'accès aux contacts pour afficher la météo. Une animatrice explique que cette autorisation n'est pas nécessaire à la fonction annoncée. » Cela justifie la réponse : Si l'accès demandé correspond au service."},{"number":13,"points":15,"correct":"A","options":["Maintenir plusieurs voies d'accès au service","Supprimer les formulaires","Réserver les appels aux informaticiens","Obliger chacun à acheter un ordinateur"],"passage":"Un service municipal conserve un accueil téléphonique en parallèle du portail en ligne. Il ne souhaite pas que l'absence d'équipement empêche une démarche.\n\nLes usagers peuvent consulter les mêmes informations essentielles quel que soit le canal choisi. Le personnel est formé pour expliquer les différences de procédure sans renvoyer systématiquement les personnes vers un ordinateur. Le service souhaite conserver la simplicité du portail pour ceux qui l'utilisent, tout en regardant ce qui reste possible pour les autres. Les responsables suivront les temps d'attente, car une alternative annoncée mais difficile à joindre ne constitue pas nécessairement un accès réel.","question":"Quel objectif est poursuivi ?","explanation":"Le passage indique : « Un service municipal conserve un accueil téléphonique en parallèle du portail en ligne. Il ne souhaite pas que l'absence d'équipement empêche une démarche. » Cela justifie la réponse : Maintenir plusieurs voies d'accès au service."},{"number":14,"points":15,"correct":"D","options":["Rendre les photos publiques","Augmenter automatiquement la qualité des images","Supprimer le besoin de classement","Limiter les conséquences de la perte de l'appareil"],"passage":"Un atelier montre comment sauvegarder ses photos sur un second support. Une copie située seulement sur le téléphone disparaîtrait avec lui en cas de perte.\n\nLes animateurs distinguent une sauvegarde et une simple copie restée dans le même appareil. Les participants apprennent aussi à vérifier qu'ils peuvent ouvrir les documents sur le second support. Le cours ne promet pas qu'une opération unique protégera définitivement tous les fichiers. Il propose une organisation régulière, adaptée au volume et à l'importance des données. Chacun prépare un premier essai avec des images fictives avant de choisir ses propres documents.","question":"À quoi sert la seconde copie ?","explanation":"Le passage indique : « Un atelier montre comment sauvegarder ses photos sur un second support. Une copie située seulement sur le téléphone disparaîtrait avec lui en cas de perte. » Cela justifie la réponse : Limiter les conséquences de la perte de l'appareil."},{"number":15,"points":15,"correct":"C","options":["Le nombre de fenêtres de la salle","Le prix du papier","Le rythme de l'interaction","La couleur du bâtiment"],"passage":"Des habitants testent une nouvelle borne. Ils signalent que les boutons sont lisibles mais que le temps laissé pour répondre est trop court.\n\nCertains habitants ont besoin de relire une consigne ou d'obtenir une explication avant d'appuyer. Les concepteurs avaient surtout testé la borne avec des personnes connaissant déjà les démarches. Ils vont donc revoir le délai et permettre de demander plus de temps. Les essais suivants comprendront des profils différents. L'équipe souhaite distinguer une difficulté liée au contenu et une difficulté produite par le rythme imposé à l'écran.","question":"Quel aspect doit être amélioré ?","explanation":"Le passage indique : « Des habitants testent une nouvelle borne. Ils signalent que les boutons sont lisibles mais que le temps laissé pour répondre est trop court. » Cela justifie la réponse : Le rythme de l'interaction."},{"number":16,"points":15,"correct":"C","options":["Le livre reste acquis pour toujours","L'emprunteur doit imprimer chaque page","Le droit de lecture est temporaire","Le prêt n'a aucune durée"],"passage":"Une bibliothèque prête des livres numériques. Le prêt s'arrête automatiquement à la date prévue ; le document ne devient pas un achat définitif.\n\nLa bibliothèque explique les possibilités de renouvellement et les conditions de téléchargement. Les lecteurs peuvent demander une démonstration s'ils découvrent le service. Les fichiers empruntés ne doivent pas être confondus avec ceux qu'ils ont achetés ailleurs. Les responsables souhaitent que chacun comprenne les droits annoncés avant de commencer un livre, notamment pendant un voyage.","question":"Quelle distinction est précisée ?","explanation":"Le passage indique : « Une bibliothèque prête des livres numériques. Le prêt s'arrête automatiquement à la date prévue ; le document ne devient pas un achat définitif. » Cela justifie la réponse : Le droit de lecture est temporaire."},{"number":17,"points":15,"correct":"C","options":["La couleur du câble","Le nombre de publicités","La possibilité de changer d'outil plus tard","La taille du logo"],"passage":"Une équipe choisit un outil de messagerie après un essai commun. Elle évalue aussi la facilité de quitter le service et d'exporter les données.\n\nLes salariés comparent les formats obtenus et regardent si les conversations utiles restent compréhensibles hors de l'outil. Ils souhaitent éviter une dépendance découverte uniquement au moment du départ. Cette vérification ne signifie pas que le groupe prévoit déjà d'abandonner le service. Elle sert à conserver une marge de décision si les besoins, les tarifs ou les règles changent.","question":"Quel critère dépasse l'usage immédiat ?","explanation":"Le passage indique : « Une équipe choisit un outil de messagerie après un essai commun. Elle évalue aussi la facilité de quitter le service et d'exporter les données. » Cela justifie la réponse : La possibilité de changer d'outil plus tard."},{"number":18,"points":15,"correct":"C","options":["Faire confiance à toute copie visuelle","Télécharger tous les fichiers proposés","Vérifier l'adresse plutôt que le seul aspect","Ignorer les informations du navigateur"],"passage":"Un atelier apprend à repérer l'adresse exacte d'un site. Une page qui ressemble à un service connu peut être hébergée ailleurs.\n\nLes participants observent des exemples fictifs où un détail du nom change alors que le logo paraît familier. Ils apprennent à retrouver le service par un moyen connu plutôt qu'à suivre immédiatement un lien reçu. Le formateur souhaite ralentir le geste lorsque la demande semble inhabituelle. Il ne promet pas une méthode qui remplacerait toute vérification future.","question":"Quelle précaution est enseignée ?","explanation":"Le passage indique : « Un atelier apprend à repérer l'adresse exacte d'un site. Une page qui ressemble à un service connu peut être hébergée ailleurs. » Cela justifie la réponse : Vérifier l'adresse plutôt que le seul aspect."},{"number":19,"points":15,"correct":"D","options":["La publication est obligatoire après réception","Les familles ne peuvent jamais regarder les photos","Toute image de groupe doit être vendue","Recevoir une image ne suffit pas à autoriser sa diffusion"],"passage":"Une école demande aux familles de ne pas diffuser les images de groupe sans vérifier les autorisations. Une photo reçue ne donne pas automatiquement le droit de la publier.\n\nLes organisateurs recueilleront les choix avant le prochain événement et indiqueront quelles images peuvent être utilisées sur les supports du groupe. Les familles pourront poser une question sans devoir se justifier devant tout le monde. L'école veut éviter qu'une habitude de partage transforme un souvenir reçu en autorisation supposée générale.","question":"Quelle limite est rappelée ?","explanation":"Le passage indique : « Une école demande aux familles de ne pas diffuser les images de groupe sans vérifier les autorisations. Une photo reçue ne donne pas automatiquement le droit de la publier. » Cela justifie la réponse : Recevoir une image ne suffit pas à autoriser sa diffusion."},{"number":20,"points":21,"correct":"A","options":["Pour améliorer la conception du service","Pour supprimer automatiquement les dossiers","Pour éviter toute correction","Pour classer publiquement les usagers"],"passage":"Une administration simplifie ses formulaires numériques avec les usagers. Les erreurs fréquentes servent à identifier des consignes peu claires, et pas seulement à constater l'inattention des personnes. Les agents relisent les demandes avec des personnes connaissant peu la procédure. Ils observent où les utilisateurs hésitent et quels mots produisent des interprétations différentes. Le service souhaite garder les informations nécessaires, mais les présenter au moment où elles sont utiles. Les modifications seront testées sur de nouveaux exemples avant d'être généralisées. Un formulaire plus court ne sera pas automatiquement meilleur si les étapes supprimées empêchent encore de comprendre ce qui est demandé.","question":"Comment les erreurs sont-elles utilisées ?","explanation":"Le passage indique : « Une administration simplifie ses formulaires numériques avec les usagers. Les erreurs fréquentes servent à identifier des consignes peu claires, et pas seulement à constater l'inattention des personnes. » Cela justifie la réponse : Pour améliorer la conception du service."},{"number":21,"points":21,"correct":"D","options":["L'impossibilité d'écrire sans internet","Le manque de papier","La disparition obligatoire du fichier","La réunion de modifications concurrentes"],"passage":"Un logiciel permet de travailler sans connexion puis de synchroniser les documents. L'équipe vérifie les conflits de versions lorsque deux personnes ont modifié le même fichier hors ligne. Les documents gardent une trace des changements et les auteurs peuvent expliquer ce qu'ils souhaitaient modifier. Elle veut savoir comment réagir lorsque la réunion automatique des modifications produit un résultat ambigu. Les personnes ne seront pas invitées à considérer tout fichier final comme correct simplement parce qu'une synchronisation s'est terminée sans afficher de message d'erreur.","question":"Quel problème doit être géré ?","explanation":"Le passage indique : « Un logiciel permet de travailler sans connexion puis de synchroniser les documents. L'équipe vérifie les conflits de versions lorsque deux personnes ont modifié le même fichier hors ligne. » Cela justifie la réponse : La réunion de modifications concurrentes."},{"number":22,"points":21,"correct":"B","options":["Le classement chronologique des dates","La concentration de l'attention sur quelques avis","L'apparition de nouveaux commentaires","La possibilité de lire les avis récents"],"passage":"Une plateforme affiche les avis dans l'ordre de publication plutôt que selon leur popularité. Elle souhaite éviter que les premiers avis très appréciés occupent durablement toute la visibilité. Les lecteurs pourront toujours rechercher un ancien avis ou examiner les réponses reçues. Le changement ne garantit pas que toutes les contributions seront lues autant, mais modifie ce qui apparaît en premier. La plateforme souhaite expliquer cette règle pour que le classement ne soit pas interprété comme une mesure neutre de qualité.","question":"Quel effet cherche-t-elle à limiter ?","explanation":"Le passage indique : « Une plateforme affiche les avis dans l'ordre de publication plutôt que selon leur popularité. Elle souhaite éviter que les premiers avis très appréciés occupent durablement toute la visibilité. » Cela justifie la réponse : La concentration de l'attention sur quelques avis."},{"number":23,"points":21,"correct":"A","options":["Conserver ses documents avant de partir","Transférer les fichiers sans accord à la publicité","Interdire la suppression du compte","Rester abonné sans le savoir"],"passage":"Un service propose de supprimer un compte tout en permettant de récupérer ses documents auparavant. Cette étape évite de confondre départ du service et perte souhaitée de tous les fichiers. La procédure indique les formats disponibles et demande de vérifier les copies avant la fermeture définitive. Les utilisateurs disposent d'un délai pour poser une question. Le service souhaite que le départ reste compréhensible, sans confondre fidélisation et difficulté à récupérer son travail.","question":"Quelle possibilité est offerte ?","explanation":"Le passage indique : « Un service propose de supprimer un compte tout en permettant de récupérer ses documents auparavant. Cette étape évite de confondre départ du service et perte souhaitée de tous les fichiers. » Cela justifie la réponse : Conserver ses documents avant de partir."},{"number":24,"points":21,"correct":"B","options":["Remplacer tous les échanges par le silence","Choisir le moyen de communication selon l'usage","Éviter toute trace écrite","Imposer une caméra permanente"],"passage":"Une entreprise réduit le nombre de réunions vidéo, mais conserve des échanges audio et des notes partagées. Le but est d'adapter le support au besoin, pas d'interdire la communication à distance. Les équipes précisent ce qui demande un échange immédiat et ce qui peut être lu plus tard. Elles souhaitent éviter qu'un changement d'outil augmente simplement le nombre de messages ou d'interruptions. Le bilan regardera donc l'organisation complète du travail.","question":"Quel principe guide le changement ?","explanation":"Le passage indique : « Une entreprise réduit le nombre de réunions vidéo, mais conserve des échanges audio et des notes partagées. Le but est d'adapter le support au besoin, pas d'interdire la communication à distance. » Cela justifie la réponse : Choisir le moyen de communication selon l'usage."},{"number":25,"points":21,"correct":"B","options":["Elle établit que les comptes personnels sont inutiles pour chaque exercice avancé.","Elle permet de comprendre l'usage avant de décider quelles données transmettre.","Elle supprime définitivement le besoin d'expliquer la collecte de données du service.","Elle garantit qu'aucune information n'est recueillie lors d'une utilisation ultérieure."],"passage":"Des formateurs utilisent des exercices sans compte personnel pour les premières séances. Les apprenants peuvent découvrir les fonctions avant de transmettre des informations les concernant. Les personnes peuvent décider à partir d'une expérience concrète, plutôt que remplir immédiatement une longue série de champs. Le centre veut que la découverte d'un outil ne soit pas conditionnée à une transmission de données dont l'utilité reste encore difficile à comprendre pour un débutant. À la troisième séance, certains choisissent d'ouvrir un compte après avoir essayé l'outil; d'autres préfèrent encore un exercice anonyme. Le formateur explique quelles fonctionnalités exigent réellement des informations personnelles.","question":"Pourquoi l'inscription différée renforce-t-elle la qualité du choix de l'apprenant ?","explanation":"L'apprenant comprend avant de décider d'inscrire ses données. B. D/C/A généralisent au-delà du choix progressif."},{"number":26,"points":21,"correct":"D","options":["Afficher la durée et les escaliers permettrait aux utilisateurs de suivre le meilleur trajet proposé pour gagner du temps.","L'algorithme choisit spontanément un itinéraire praticable pour les poussettes.","Expliquer les critères retenus rendrait la proposition adaptée à tous les usagers, même sans connaître leurs contraintes personnelles.","Un trajet optimisé pour la rapidité peut ignorer les contraintes de certains utilisateurs."],"passage":"Une application propose une recommandation automatique de trajet. Elle affiche aussi les critères retenus pour que l'utilisateur comprenne pourquoi un parcours est privilégié. L'utilisateur peut alors décider si le gain de temps annoncé correspond à sa situation. Il peut choisir un trajet différent lorsqu'un critère non retenu lui paraît plus important. Des retours permettront d'améliorer les informations et d'identifier les contraintes fréquentes que le service n'avait pas encore correctement prises en compte dans ses premières propositions. Le trajet le plus rapide proposé comporte des escaliers, alors que l'usager transporte une poussette. En lisant les critères, il comprend pourquoi cette option a été proposée et privilégie une autre route.","question":"Quelle limite l'explication des critères permet-elle de gérer ?","explanation":"D montre qu'un optimum calculé sur la durée peut ignorer l'accessibilité individuelle. A continue de privilégier la durée malgré la poussette, B suppose un ajustement automatique absent, C prend l'explication pour une garantie d'adéquation."},{"number":27,"points":21,"correct":"D","options":["Demander aux jeunes d'abandonner toutes les pratiques en ligne avant d'apprendre à les vérifier.","Les récits des adolescents sont utiles surtout pour indiquer aux familles les pratiques auxquelles elles devront mettre fin.","Chaque exemple doit conduire à identifier une responsabilité individuelle avant la discussion sur les moyens de vérification.","Permettre une analyse collective des risques et des ressources d'aide à partir de situations effectivement rencontrées."],"passage":"Une médiathèque accueille des adolescents pour discuter de leurs pratiques en ligne. Les animateurs partent de situations concrètes plutôt que d'un discours présentant tous les usages comme dangereux. Les participants parlent de leurs habitudes, mais aussi des moments où ils ont besoin d'aide ou de recul. Les questions seront reprises lors d'une séance suivante avec les familles intéressées, dans un cadre respectant les choix de chacun. Un jeune explique avoir partagé une image sans vérifier son origine; les autres discutent de moyens de contrôle sans réduire la séance à la recherche d'un coupable. Les familles reçoivent ensuite des pistes adaptées.","question":"Quel bénéfice l'approche fondée sur des exemples vécus cherche-t-elle à produire ?","explanation":"D utilise des cas vécus pour analyser collectivement les risques et les ressources d'aide. A en fait d'abord une liste de pratiques à interdire; B transforme les récits en consignes aux familles; C impose une désignation individuelle de responsabilité que les animateurs évitent."},{"number":28,"points":21,"correct":"C","options":["Les essais menés avec un lecteur d'écran rendent inutiles les vérifications auprès des autres visiteurs.","Une amélioration de l'accessibilité profite nécessairement à tous dans exactement les mêmes proportions.","Certaines modifications facilitent plusieurs parcours, sans prouver qu'elles résolvent toutes les situations d'accès.","Les difficultés spécifiques disparaissent dès que les menus sont plus explicites."],"passage":"Un site simplifie ses menus après des tests avec des lecteurs d'écran. Les améliorations facilitent aussi la navigation de nombreux autres visiteurs. Les menus deviennent plus prévisibles et les formulaires plus explicites. Certains visiteurs sans outil particulier disent aussi trouver plus rapidement la bonne page. Elle observe leurs effets sur des parcours variés, tout en continuant à vérifier les besoins spécifiques qui ne seraient pas résolus par une modification générale de la présentation. Des essais montrent que les intitulés de boutons devenus plus explicites aident un utilisateur de lecteur d'écran et une personne sans handicap qui découvre le site. Les besoins plus spécifiques font toutefois l'objet de tests distincts.","question":"Quelle conclusion est justifiée par ces deux observations ?","explanation":"Les bénéfices sont transversaux mais non exhaustifs. C conserve les deux nuances; B/D sur-généralisent, A écarte le suivi."},{"number":29,"points":21,"correct":"C","options":["La limitation du nombre de fonctions rend impossible une approche autonome du numérique.","La découverte de fonctions secondaires n'a d'intérêt que si les participants maîtrisent déjà toute l'interface.","Une tâche concrète rend les gestes compréhensibles et révèle les difficultés rencontrées, en pratique.","Une démarche réelle prouve que les participants n'auront plus besoin d'aide lors des tâches suivantes."],"passage":"Une association organise des ateliers en petits groupes. Les questions techniques y sont liées à une tâche réelle, comme retrouver un justificatif, afin d'éviter des manipulations sans objectif compréhensible. Les participants peuvent expliquer les étapes qu'ils comprennent et celles où ils ont besoin d'un soutien. Les formateurs évitent de multiplier les fonctions avant que la première démarche soit maîtrisée. Pour apprendre à joindre un justificatif, les participants accomplissent leur propre démarche guidée. Le formateur note où chacun se bloque, puis introduit la fonction suivante lorsqu'elle devient nécessaire.","question":"Pourquoi le formateur ne commence-t-il pas par présenter toutes les fonctionnalités ?","explanation":"Le contexte réel donne sens aux gestes et ordonne les apprentissages. C; les autres imposent des conditions ou des conclusions absolues."},{"number":30,"points":26,"correct":"A","options":["Un partage trop large peut résulter de paramètres initiaux laissés inchangés par l'utilisateur.","La possibilité pour des utilisateurs de choisir volontairement un partage plus large.","La confusion entre les données nécessaires au service et l'ensemble des informations du compte.","L'absence de tout contrôle ultérieur lorsque le réglage a été sélectionné à l'inscription."],"passage":"Les réglages par défaut influencent les pratiques, car de nombreux utilisateurs ne les modifient pas. Un service choisit donc un partage limité au départ. La possibilité d'élargir ensuite l'accès demeure, mais elle résulte d'une décision explicite. Les explications montrent comment élargir l'accès si une personne le souhaite. Le service veut que cette décision soit compréhensible et réversible, plutôt qu'un changement que l'utilisateur découvrirait après la diffusion de ses informations à un public inattendu. Lors d'un essai, peu d'utilisateurs changent le réglage initial. Ceux qui souhaitent rendre un dossier public disposent néanmoins d'une option clairement expliquée qu'ils peuvent annuler ensuite.","question":"Quel risque le réglage de confidentialité limité par défaut cherche-t-il à réduire ?","explanation":"Les valeurs par défaut influencent les choix réels; limiter l'exposition protège les inattentifs sans supprimer le choix. A."},{"number":31,"points":26,"correct":"C","options":["Elle retire des fonctions peu fréquentes pour accélérer les opérations ordinaires.","Elle place toutes les fonctions sur la page principale afin d'éviter tout apprentissage des menus.","Mettre en avant les tâches courantes tout en gardant l'accès aux fonctions avancées.","Elle limite le service aux utilisateurs novices en supprimant les besoins spécialisés."],"passage":"Une interface peut afficher beaucoup de fonctions et paraître complète. Si les actions courantes sont difficiles à trouver, cette richesse devient un obstacle. Les concepteurs retirent des éléments de l'écran principal sans supprimer les fonctions avancées accessibles ailleurs. Ils souhaitent réduire le temps de recherche, sans décider que les fonctions moins fréquentes ne servent plus à personne ou doivent disparaître du service. Un bouton fréquemment utilisé passe sur l'écran d'accueil, tandis qu'une option experte rejoint un sous-menu clairement identifié. Le nombre total d'actions disponibles reste identique.","question":"Comment l'équipe distingue-t-elle simplification de l'écran et appauvrissement du service ?","explanation":"L'architecture change, non les capacités. C. A/B/D confondent visibilité et disponibilité."},{"number":32,"points":26,"correct":"B","options":["Un format récent élimine le besoin de conserver des informations sur l'origine.","Deux fichiers intacts peuvent devenir illisibles ou perdre leur contexte à long terme.","La numérisation initiale suffit à rendre tout document pérenne sans suivi technique.","Le nombre de copies garantit la possibilité de comprendre la provenance des documents."],"passage":"Une organisation numérise ses archives. Elle doit aussi conserver des descriptions, des formats lisibles et des copies fiables. Transformer un document en fichier ne suffit pas à garantir qu'il pourra être retrouvé et compris dix ans plus tard. Les archivistes contrôlent donc régulièrement les supports et les informations associées. Ils prévoient aussi les changements de format, afin qu'un fichier conservé matériellement ne devienne pas un document impossible à lire ou à interpréter plus tard. Deux fichiers ont des copies intactes dix ans après numérisation. L'un conserve la description de son origine et se lit avec un format maintenu; l'autre a perdu ces informations et ne s'ouvre plus avec les logiciels récents.","question":"Quelle distinction illustrent les deux fichiers conservés ?","explanation":"Un fichier intact peut être illisible ou sans contexte. B. D/C/A attribuent trop au stockage ou au format."},{"number":33,"points":26,"correct":"D","options":["Concentrer le contrôle sur les formats les plus fréquents permettrait d'interpréter le taux global sans examiner les cas minoritaires.","Analyser les groupes permet d'expliquer les erreurs sans réexaminer les exemples d'entraînement.","Le nombre total de réponses correctes resterait représentatif dès lors que les demandes au format minoritaire sont peu nombreuses.","Parce qu'un niveau moyen élevé peut masquer des erreurs concentrées sur certains profils de demandes."],"passage":"Un outil automatisé classe les demandes selon les exemples utilisés pour le préparer. Si ces exemples représentent mal certaines situations, l'efficacité moyenne peut masquer des erreurs répétées pour un groupe. Une évaluation doit donc regarder la répartition des erreurs, pas seulement leur total. Ils pourront alors préparer des tests complémentaires, plutôt que publier seulement un taux global encourageant qui laisserait certains problèmes durablement invisibles. Le système affiche 92 % de réponses correctes au total, mais seulement 60 % pour des demandes rédigées dans un format minoritaire. L'équipe vérifie désormais les résultats pour chaque type de cas.","question":"Pourquoi le taux global ne suffit-il pas à juger le dispositif ?","explanation":"D rappelle qu'une moyenne de 92 % peut cacher seulement 60 % pour un format minoritaire. A ignore précisément ce groupe, B surinterprète le contrôle par groupe comme diagnostic complet et C confond forte performance globale et fiabilité pour chaque profil."},{"number":34,"points":26,"correct":"A","options":["Elles distinguent l'envoi d'un message d'une attente de disponibilité immédiate, afin de protéger les limites personnelles.","Elles font dépendre la qualité du travail du nombre de réponses envoyées en dehors des heures habituelles.","Elles garantissent que les mêmes horaires de connexion soient imposés à tous les salariés.","Elles permettent de supprimer les messages écrits au profit des seuls échanges en direct."],"passage":"Le travail à distance permet une présence géographique plus souple, mais peut rendre les limites horaires moins visibles. Une équipe définit des temps sans attente de réponse. La souplesse ne signifie pas une disponibilité permanente ; elle demande aussi des règles partagées de déconnexion. Les salariés peuvent ainsi organiser leur journée sans devoir interpréter chaque silence comme un refus de travailler ou chaque message tardif comme une demande immédiate. Un salarié envoie un document tard le soir sans attendre de réponse; un collègue, ignorant cette convention, se croit tenu de répondre. L'équipe inscrit les règles d'urgence et les plages sans réponse attendue.","question":"Pourquoi les règles partagées sont-elles nécessaires malgré la souplesse du télétravail ?","explanation":"Les conventions explicites évitent l'obligation implicite de répondre. A. C/D/B suppriment la flexibilité."},{"number":35,"points":26,"correct":"C","options":["Reproduire les étapes de l'ancienne interface puis rechercher les boutons déplacés sans consulter les consignes.","Attendre les consignes du formateur avant toute navigation pour éviter les erreurs liées aux mises à jour.","Savoir chercher une information pertinente, tester une procédure et contrôler sa validité, après une mise à jour.","Connaître plusieurs emplacements possibles pour chaque fonction sans vérifier leur fonctionnement après le changement."],"passage":"Une formation numérique promet l'autonomie après quelques séances. Les outils changent pourtant rapidement. Les formateurs privilégient donc des repères pour chercher de l'aide, comprendre une consigne et vérifier une information, plutôt qu'une liste de gestes liée à un seul écran. Les personnes pourront réutiliser ces repères lorsqu'une fonction change de place. Le centre veut transmettre une manière de chercher et de vérifier, sans promettre qu'un seul cours rendrait toutes les interfaces futures immédiatement familières et faciles. Une application change l'ordre de ses menus après une mise à jour. Un ancien apprenant retrouve pourtant la procédure en lisant l'aide, en vérifiant les étapes et en contrôlant le résultat.","question":"Quel apprentissage permet de continuer après ce changement ?","explanation":"C correspond à des repères transférables pour rechercher, tester et contrôler. A/D restent centrées sur la mémorisation d'emplacements; B crée une dépendance à l'accompagnateur."},{"number":36,"points":33,"correct":"C","options":["Parce qu'un objectif de consultation longue produit un classement comparable à celui qui privilégie la diversité.","Parce que les données initiales doivent être modifiées dès que la plateforme choisit une autre priorité de classement.","Parce que les priorités du classement influencent les résultats affichés, selon des objectifs de calcul distincts.","Parce que la neutralité dépend principalement du nombre de recommandations affichées et non de leur ordre."],"passage":"Une plateforme présente ses recommandations comme neutres parce qu'elles sont calculées. Pourtant, elle doit choisir ce qu'elle optimise : durée de consultation, diversité ou satisfaction déclarée. Ces objectifs peuvent conduire à des sélections différentes. Un calcul n'efface pas les choix inscrits dans les critères qui le guident. Une recommandation peut être très efficace pour garder un utilisateur longtemps sur un site, sans lui faire découvrir des sources différentes. Une autre peut lui proposer plus de variété, mais demander davantage d'effort au début. Le service doit donc expliquer ses priorités et observer leurs conséquences. Les responsables souhaitent que le public puisse discuter ces choix, plutôt que considérer la formule comme une simple description du monde. La technique apporte des moyens de calcul, mais elle ne décide pas seule de la valeur que l'on attribue à chacun des résultats recherchés. Lors d'un essai, privilégier la durée de consultation fait monter les recommandations de contenus polarisants; privilégier la variété modifie le classement sans changer les données de départ. L'équipe publie les critères de chaque version.","question":"Pourquoi le même jeu de données ne garantit-il pas un classement neutre ?","explanation":"C montre qu'une règle d'optimisation incorpore une priorité qui façonne le classement. A nie l'écart observé, B suppose une modification des données absente, D attribue la neutralité au volume affiché."},{"number":37,"points":33,"correct":"A","options":["Le travail d'assistance déplacé vers les partenaires et l'achèvement réel des démarches par les usagers.","Le nombre de dossiers commencés, même lorsque certaines personnes ne peuvent pas les terminer sans aide.","La réduction des dépenses administratives, indépendamment du temps de soutien requis par les associations.","L'économie de temps enregistrée au guichet, sans considérer les démarches déplacées vers les autres acteurs."],"passage":"Une administration remplace un guichet par une démarche en ligne. Le nombre de dossiers déposés augmente, mais les personnes en difficulté se déplacent désormais vers les associations pour obtenir de l'aide. Une simplification pour le service peut déplacer le travail d'accompagnement vers d'autres acteurs plutôt que le faire disparaître. Les bénévoles expliquent qu'ils doivent apprendre les nouvelles interfaces et accompagner des cas parfois complexes. Cette activité ne figure pas toujours dans les économies annoncées par le service public. Les responsables vont rencontrer les associations pour préciser les difficultés et garder une possibilité d'accueil direct. Ils souhaitent mesurer les démarches menées jusqu'au bout, pas seulement les formulaires commencés. Le bilan devra donc inclure les personnes qui n'ont pas réussi seules et les ressources nécessaires pour les aider, afin de comprendre si le nouveau fonctionnement simplifie réellement l'accès pour l'ensemble du public. Le service annonce un gain de dix minutes par dossier, mais une association consacre désormais vingt minutes à accompagner certaines personnes sur la nouvelle interface. Ces heures ne figurent pas dans le bilan administratif initial.","question":"Quelle information faut-il intégrer pour apprécier le gain de la dématérialisation ?","explanation":"A intègre les tâches transférées et les démarches réellement terminées. B confond commencement et aboutissement; C/D excluent le coût d'assistance observé."},{"number":38,"points":33,"correct":"D","options":["Une information détaillée permet d'accepter plus facilement, même si le refus reste accessible après plusieurs étapes.","Une option de refus demeure suffisamment claire lorsque son emplacement est décrit au bas du formulaire.","La rapidité du consentement révèle une préférence stable, sauf si l'utilisateur choisit de revenir sur sa décision.","Une option de refus présente à l'écran peut rester difficile à exercer selon sa présentation concrète."],"passage":"Un service demande le consentement avant d'utiliser des données, puis présente un formulaire très long dont le refus est difficile à trouver. Le choix existe juridiquement à l'écran, mais l'organisation de la page peut orienter fortement la décision. La présence d'une option ne suffit pas à garantir qu'elle soit aussi facile à comprendre et à exercer que les autres. Les utilisateurs peuvent accepter rapidement pour terminer une tâche urgente, même s'ils auraient préféré limiter l'utilisation de leurs informations. Une association propose donc des choix présentés avec la même lisibilité et un résumé des effets principaux. Les responsables souhaitent conserver les explications détaillées pour ceux qui en ont besoin, sans rendre le refus plus compliqué que l'accord. Les essais seront menés avec des personnes découvrant le service. Deux écrans offrent « Accepter » en gros bouton et « Refuser » derrière plusieurs liens. Lors d'un test, des participants qui souhaitaient limiter leurs données acceptent par impatience; le service rééquilibre la visibilité.","question":"Quelle faiblesse du recueil de consentement ce test met-il en évidence ?","explanation":"D souligne que l'asymétrie de présentation limite le choix réel malgré la présence juridique d'une option. A/B justifient une difficulté d'accès au refus; C attribue trop de sens aux acceptations précipitées."},{"number":39,"points":33,"correct":"A","options":["La reprise des opérations et le rapprochement des résultats après redémarrage, car une procédure de secours ne garantit pas à elle seule la fiabilité finale.","Le temps minimal d'interruption rapporté dans chaque service, puisque les deux équipes ont continué leur travail manuel sans attendre la remise en route du logiciel et ont donc assuré les opérations attendues.","La quantité de travail manuel permet d'évaluer la fiabilité des paramètres informatiques retrouvés après la panne.","La confirmation finale d'un client peut se substituer à la vérification interne des calculs pendant le redémarrage."],"passage":"Un logiciel rend une tâche plus rapide. Les professionnels conservent néanmoins un moyen de travailler en cas de panne et des connaissances pour contrôler les résultats. Ils ne rejettent pas l'automatisation ; ils évitent qu'une commodité se transforme en dépendance sans recours. La maîtrise d'un outil comprend aussi la possibilité de vérifier et de s'en passer temporairement. Des exercices permettent de repérer un résultat inhabituel et de reprendre une tâche avec un autre moyen. Les nouveaux collègues reçoivent ces repères lors de leur arrivée, pour éviter qu'ils disparaissent avec les personnes les plus expérimentées. L'organisation souhaite profiter du gain de temps sans perdre la compréhension de ce qui est réalisé. Le bilan portera donc sur la vitesse, mais aussi sur la capacité à expliquer les décisions et à continuer lors d'un incident. Lors d'une panne, l'équipe exécute une procédure manuelle déjà exercée. À la reprise du logiciel, elle compare les résultats et détecte une anomalie issue d'un paramètre mal réglé. Un audit compare ensuite deux incidents. Lors du premier, l'équipe applique une procédure manuelle et continue le service, mais conserve un ancien paramètre dans le logiciel lors de sa remise en route. Un contrôle croisé découvre l'erreur avant l'envoi des résultats aux clients. Lors du second, la procédure de secours permet également de poursuivre les opérations, mais aucun rapprochement n'est effectué à la reprise; une anomalie de calcul n'est identifiée que par un client plusieurs jours plus tard. Les deux équipes disposent donc d'une capacité minimale de continuité en cas de panne, sans posséder le même niveau de vérification après le redémarrage. Le responsable estime qu'un tableau indiquant seulement les minutes d'interruption masquerait cette différence. Il veut suivre séparément la capacité à terminer les tâches, à expliciter les résultats produits et à détecter les anomalies après rétablissement du système.","question":"Quel indicateur distingue le mieux une simple continuité de service d'une maîtrise vérifiable du processus automatisé ?","explanation":"A associe la capacité de continuer à travailler et la vérification des calculs à la reprise du logiciel. B se limite à l'interruption; C confond volume de travail manuel et bon paramétrage; D remplace à tort le contrôle interne par une détection éventuelle du client."}]}$paper_13$::jsonb),
('tcf-reading-14','tcf-reading-2026-11-distractor-polish-v5',$paper_14${"id":"tcf-reading-14","title":"TCF Reading · Test 14","seconds":3600,"version":"tcf-reading-2026-11-distractor-polish-v5","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["Vendredi soir obligatoirement","Le mois suivant","Jamais","Avant son envoi"],"passage":"Le journal du quartier recevra vos annonces jusqu'au vendredi midi. Les textes arrivés ensuite paraîtront le mois suivant.\n\nUn message confirmera la réception des annonces retenues. Merci d'indiquer une date et un contact pour permettre aux lecteurs de demander des renseignements.","question":"Quand une annonce tardive sera-t-elle publiée ?","explanation":"Le passage indique : « Le journal du quartier recevra vos annonces jusqu'au vendredi midi. Les textes arrivés ensuite paraîtront le mois suivant. » Cela justifie la réponse : Le mois suivant."},{"number":2,"points":3,"correct":"D","options":["L'accès est réservé aux journalistes","Les lecteurs doivent apporter un article","La réunion est payante","La capacité est limitée"],"passage":"La conférence de rédaction est ouverte aux lecteurs mercredi. Merci de réserver une place ; la salle est petite.\n\nLes personnes inscrites recevront les horaires et le lieu d'accueil.","question":"Pourquoi faut-il réserver ?","explanation":"Le passage indique : « La conférence de rédaction est ouverte aux lecteurs mercredi. Merci de réserver une place ; la salle est petite. » Cela justifie la réponse : La capacité est limitée."},{"number":3,"points":3,"correct":"D","options":["Une attribution à un autre photographe","Toute publicité commerciale","Une vente sans accord","Un travail scolaire"],"passage":"Les photos de l'exposition peuvent être utilisées pour un travail scolaire en citant leur auteur. L'usage commercial nécessite un accord séparé.\n\nLes conditions sont indiquées sur le site avec les noms des photographes.","question":"Quel usage est autorisé sous condition de citation ?","explanation":"Le passage indique : « Les photos de l'exposition peuvent être utilisées pour un travail scolaire en citant leur auteur. L'usage commercial nécessite un accord séparé. » Cela justifie la réponse : Un travail scolaire."},{"number":4,"points":3,"correct":"A","options":["À la mairie","Au guichet de la piscine seulement","Dans chaque train","Uniquement dans les boîtes aux lettres"],"passage":"Le bulletin ne sera pas distribué dans les boîtes aux lettres cette semaine. Il reste disponible à la mairie.\n\nLa rédaction publiera aussi une version numérique pour les lecteurs qui ne peuvent pas se déplacer.","question":"Où peut-on le consulter ?","explanation":"Le passage indique : « Le bulletin ne sera pas distribué dans les boîtes aux lettres cette semaine. Il reste disponible à la mairie. » Cela justifie la réponse : À la mairie."},{"number":5,"points":9,"correct":"C","options":["La taille du fichier uniquement","Le nombre de photos du pont","La date de l'information","Le nom de tous les lecteurs"],"passage":"Je t'ai transmis un article ancien par erreur. Vérifie la date avant de partager l'annonce de fermeture du pont.\n\nLe nouveau texte de la mairie indique que la circulation a déjà repris. Je préfère te prévenir avant que tu organises un autre trajet à partir de mon premier envoi.","question":"Quelle vérification est demandée ?","explanation":"Le passage indique : « Je t'ai transmis un article ancien par erreur. Vérifie la date avant de partager l'annonce de fermeture du pont. » Cela justifie la réponse : La date de l'information."},{"number":6,"points":9,"correct":"D","options":["Une publication automatique intégrale","Un vote sur son identité","Une diffusion sans contact préalable","Une confirmation avec le témoin"],"passage":"Notre podcast accueille des témoignages courts. Nous vous rappellerons avant diffusion pour confirmer les passages retenus.\n\nLes enregistrements seront montés pour rendre les échanges plus faciles à suivre. Vous pourrez poser vos questions sur ce fonctionnement avant de confirmer votre participation au programme.","question":"Quelle étape est prévue ?","explanation":"Le passage indique : « Notre podcast accueille des témoignages courts. Nous vous rappellerons avant diffusion pour confirmer les passages retenus. » Cela justifie la réponse : Une confirmation avec le témoin."},{"number":7,"points":9,"correct":"B","options":["Une annonce uniquement promotionnelle","Un portrait comportant des questions critiques","Un catalogue de prix sans entretien","Un texte rédigé par tous les clients"],"passage":"J'aimerais interviewer un artisan, pas réaliser une publicité. Je lui demanderai aussi quelles difficultés il rencontre.\n\nJe préparerai des questions sur ses choix, ses outils et l'organisation de ses journées. Le lecteur doit pouvoir comprendre son activité, pas seulement connaître les produits qu'il souhaite vendre.","question":"Quel type de contenu est recherché ?","explanation":"Le passage indique : « J'aimerais interviewer un artisan, pas réaliser une publicité. Je lui demanderai aussi quelles difficultés il rencontre. » Cela justifie la réponse : Un portrait comportant des questions critiques."},{"number":8,"points":9,"correct":"B","options":["Supprimer les annonces de service","Rendre les informations urgentes plus visibles","Augmenter le nombre d'alertes sans distinction","Interdire toute discussion"],"passage":"Le groupe de discussion réserve les messages urgents aux informations de service. Les débats généraux se tiennent dans un autre espace.\n\nLes membres pourront continuer à discuter sans rendre difficile la recherche d'une annonce importante au milieu des réactions.","question":"Pourquoi séparer les espaces ?","explanation":"Le passage indique : « Le groupe de discussion réserve les messages urgents aux informations de service. Les débats généraux se tiennent dans un autre espace. » Cela justifie la réponse : Rendre les informations urgentes plus visibles."},{"number":9,"points":9,"correct":"A","options":["Le nom de l'association","Le sujet complet de l'article","Toutes les citations","La date de l'entretien"],"passage":"Merci de corriger le nom de mon association dans l'article. Les propos cités sont exacts ; seule cette mention pose problème.\n\nUne note courte permettra aux lecteurs de retrouver le bon organisme sans modifier le sens de l'entretien.","question":"Quelle correction est demandée ?","explanation":"Le passage indique : « Merci de corriger le nom de mon association dans l'article. Les propos cités sont exacts ; seule cette mention pose problème. » Cela justifie la réponse : Le nom de l'association."},{"number":10,"points":9,"correct":"B","options":["Seuls les élus peuvent témoigner","Un témoignage représente d'abord une expérience individuelle","Chaque récit décrit nécessairement toute la population","Les souvenirs doivent tous être identiques"],"passage":"Nous préparons une émission sur les souvenirs du quartier. Les participants peuvent raconter une expérience personnelle sans prétendre parler pour tous les habitants.\n\nLes personnes pourront aussi préférer un texte ou une photographie à un enregistrement de leur voix pendant la rencontre.","question":"Quelle limite est reconnue ?","explanation":"Le passage indique : « Nous préparons une émission sur les souvenirs du quartier. Les participants peuvent raconter une expérience personnelle sans prétendre parler pour tous les habitants. » Cela justifie la réponse : Un témoignage représente d'abord une expérience individuelle."},{"number":11,"points":15,"correct":"C","options":["Éviter toute lecture critique","Prouver que toute analyse est impossible","Permettre de vérifier le point de départ","Remplacer l'enquête par un titre"],"passage":"Un journaliste publie le document à l'origine de son enquête. Les lecteurs peuvent ainsi distinguer la source et l'analyse qu'il en propose.\n\nLe document est accompagné de sa date et d'une indication sur la manière dont il a été obtenu. Les journalistes expliquent les passages qui leur paraissent importants et les limites de ce qu'ils peuvent en déduire. Les lecteurs peuvent ainsi examiner le raisonnement sans devoir accepter une conclusion sur la seule réputation du média. La rédaction souhaite rendre le travail plus lisible, pas prétendre qu'une source brute supprimerait tout besoin d'analyse ou donnerait automatiquement une interprétation identique à toutes les personnes qui la consultent.","question":"Quel intérêt présente cette publication ?","explanation":"Le passage indique : « Un journaliste publie le document à l'origine de son enquête. Les lecteurs peuvent ainsi distinguer la source et l'analyse qu'il en propose. » Cela justifie la réponse : Permettre de vérifier le point de départ."},{"number":12,"points":15,"correct":"B","options":["Le nom du fabricant du papier","Le moment de la prise de vue","Le prix de l'appareil","La largeur du cadre"],"passage":"Une photographie montre une rue vide à l'aube. Utilisée pour illustrer l'activité de toute la journée, elle peut donner une impression trompeuse.\n\nLa légende devrait préciser les conditions et éviter de présenter ce moment comme représentatif de toutes les heures. Des observations complémentaires pourraient montrer les variations de fréquentation. Les élèves de l'atelier comparent plusieurs usages de la même image et discutent des impressions produites.","question":"Quelle information manque pour l'interpréter ?","explanation":"Le passage indique : « Une photographie montre une rue vide à l'aube. Utilisée pour illustrer l'activité de toute la journée, elle peut donner une impression trompeuse. » Cela justifie la réponse : Le moment de la prise de vue."},{"number":13,"points":15,"correct":"A","options":["Éviter une confusion temporelle","Augmenter le volume sonore","Interdire la rediffusion","Cacher l'origine du programme"],"passage":"Une radio locale rediffuse une émission en signalant clairement sa date initiale. Les informations pratiques anciennes ne doivent pas être prises pour des annonces actuelles.\n\nLe présentateur rappelle également le contexte avant les passages consacrés aux services du quotidien. Certaines questions restent intéressantes longtemps, mais des horaires ou des procédures peuvent avoir changé depuis l'entretien. Elle souhaite conserver la valeur des archives sans encourager des démarches à partir d'une information devenue ancienne. Les auditeurs pourront retrouver la version d'origine, avec les précisions permettant de la distinguer d'une annonce nouvelle destinée au public de cette semaine.","question":"Pourquoi afficher cette date ?","explanation":"Le passage indique : « Une radio locale rediffuse une émission en signalant clairement sa date initiale. Les informations pratiques anciennes ne doivent pas être prises pour des annonces actuelles. » Cela justifie la réponse : Éviter une confusion temporelle."},{"number":14,"points":15,"correct":"D","options":["Désigner un titre sans lire","Éviter toute comparaison","Mémoriser tous les titres","Identifier un choix de présentation"],"passage":"Un atelier compare deux titres portant sur le même rapport. Les participants repèrent les aspects sélectionnés et ceux qui ne sont pas mentionnés.\n\nLes groupes lisent ensuite les extraits correspondants pour voir ce que chaque titre permet réellement d'affirmer. Un titre peut être exact tout en donnant la priorité à un aspect particulier. Les animateurs souhaitent que les lecteurs apprennent à reconnaître ce travail de sélection, sans conclure que toutes les formulations sont nécessairement trompeuses. Les participants proposeront une autre version et expliqueront leur choix.","question":"Quelle compétence est travaillée ?","explanation":"Le passage indique : « Un atelier compare deux titres portant sur le même rapport. Les participants repèrent les aspects sélectionnés et ceux qui ne sont pas mentionnés. » Cela justifie la réponse : Identifier un choix de présentation."},{"number":15,"points":15,"correct":"C","options":["La taille des bureaux","Le poids du papier","La nature des textes publiés","La profession de tous les abonnés"],"passage":"Une rédaction distingue les tribunes d'opinion des enquêtes d'information. Les rubriques ne demandent pas au lecteur la même manière d'évaluer les arguments.\n\nLes tribunes peuvent défendre une position et doivent être lues comme des arguments signés. La rédaction précise cependant que la séparation des rubriques ne dispense pas de vérifier une affirmation lorsqu'elle apparaît dans un texte d'opinion. Le journal souhaite rendre sa présentation plus claire, sans créer une catégorie dans laquelle les auteurs pourraient affirmer n'importe quoi en se contentant de rappeler que le texte exprime leur point de vue personnel.","question":"Quelle distinction est rendue visible ?","explanation":"Le passage indique : « Une rédaction distingue les tribunes d'opinion des enquêtes d'information. Les rubriques ne demandent pas au lecteur la même manière d'évaluer les arguments. » Cela justifie la réponse : La nature des textes publiés."},{"number":16,"points":15,"correct":"A","options":["La transparence sur les rectifications","L'effacement de toute responsabilité","La suppression de toutes les archives","L'interdiction de signaler une erreur"],"passage":"Le journal rectifie un chiffre et explique l'erreur dans une note. Il conserve une trace de la correction au lieu de modifier silencieusement l'article.\n\nLa note indique ce qui a changé et pourquoi l'équipe a retenu la nouvelle valeur. Les lecteurs peuvent ainsi comprendre si la correction modifie ou non la conclusion générale. La rédaction ne souhaite pas garder une donnée fausse simplement pour ne pas attirer l'attention sur l'incident. Elle veut aussi éviter qu'une modification invisible empêche de suivre le parcours d'une information déjà citée ailleurs.","question":"Quel principe applique-t-il ?","explanation":"Le passage indique : « Le journal rectifie un chiffre et explique l'erreur dans une note. Il conserve une trace de la correction au lieu de modifier silencieusement l'article. » Cela justifie la réponse : La transparence sur les rectifications."},{"number":17,"points":15,"correct":"C","options":["Le refus de consulter les habitants","Le remplacement du projet par une rumeur","Le recueil de points de vue indépendants de l'annonce","La copie exacte de la publicité"],"passage":"Un communiqué annonce un projet municipal. Avant de le reprendre, une journaliste interroge aussi les personnes concernées par ses effets.\n\nLa journaliste recueille les réactions des riverains et consulte des documents sur des réalisations comparables. Elle veut distinguer les intentions et les effets encore à vérifier. Les responsables du projet pourront répondre aux questions, mais leur présentation ne sera pas traitée comme un bilan déjà établi. Le journal souhaite que les lecteurs comprennent ce qui est annoncé et ce qui reste incertain.","question":"Quelle démarche complète le communiqué ?","explanation":"Le passage indique : « Un communiqué annonce un projet municipal. Avant de le reprendre, une journaliste interroge aussi les personnes concernées par ses effets. » Cela justifie la réponse : Le recueil de points de vue indépendants de l'annonce."},{"number":18,"points":15,"correct":"D","options":["La longueur du titre","Le prix de l'abonnement","La couleur du graphique","La taille du groupe interrogé"],"passage":"Un média publie des statistiques accompagnées du nombre de répondants. Un résultat fondé sur un petit groupe demande davantage de prudence dans sa généralisation.\n\nLe média précise aussi comment les personnes ont été choisies et dans quelles conditions elles ont répondu. Les journalistes souhaitent éviter qu'un pourcentage donne une impression de précision supérieure à celle des données. Le chiffre peut rester utile pour décrire les répondants, sans représenter automatiquement une population plus vaste. Les lecteurs pourront consulter les limites annoncées et comparer avec d'autres travaux.","question":"Quelle information aide à juger la portée du résultat ?","explanation":"Le passage indique : « Un média publie des statistiques accompagnées du nombre de répondants. Un résultat fondé sur un petit groupe demande davantage de prudence dans sa généralisation. » Cela justifie la réponse : La taille du groupe interrogé."},{"number":19,"points":15,"correct":"C","options":["Une experte ne peut avoir aucune préférence","Le métier suffit à valider toute opinion","Toutes ses opinions n'ont pas le même fondement d'expertise","Les connaissances interdisent les questions"],"passage":"Une émission invite une experte sur son domaine de recherche. Le présentateur distingue ses connaissances professionnelles de ses préférences personnelles.\n\nL'invitée peut indiquer les résultats qu'elle connaît et préciser les questions qui dépassent son travail. Le présentateur souhaite éviter de transformer une qualité professionnelle réelle en autorité générale sur tous les sujets. Les auditeurs recevront des références pour approfondir les éléments scientifiques abordés. Les préférences exprimées seront présentées comme telles, afin que chacun puisse apprécier leur statut.","question":"Pourquoi cette distinction importe-t-elle ?","explanation":"Le passage indique : « Une émission invite une experte sur son domaine de recherche. Le présentateur distingue ses connaissances professionnelles de ses préférences personnelles. » Cela justifie la réponse : Toutes ses opinions n'ont pas le même fondement d'expertise."},{"number":20,"points":21,"correct":"D","options":["Réserver l'article aux spécialistes","Remplacer toutes les preuves par des slogans","Supprimer les informations importantes","Rendre le texte accessible sans effacer ses fondements"],"passage":"Un journal souhaite élargir son lectorat. Il réduit les termes techniques, mais conserve les sources et les explications nécessaires. Simplifier la langue ne signifie pas supprimer ce qui permet de comprendre le raisonnement. Des lecteurs ont participé à la relecture des premiers essais. Ils ont signalé les mots qui gênaient la compréhension et les endroits où une explication manquait. Les journalistes ont ensuite réorganisé certains passages sans retirer les éléments qui permettent de contrôler les affirmations. Le journal souhaite une lecture plus fluide, pas une conclusion qu'il faudrait accepter sans comprendre comment elle a été construite.","question":"Quel équilibre cherche-t-il ?","explanation":"Le passage indique : « Un journal souhaite élargir son lectorat. Il réduit les termes techniques, mais conserve les sources et les explications nécessaires. Simplifier la langue ne signifie pas supprimer ce qui permet de comprendre le raisonnement. » Cela justifie la réponse : Rendre le texte accessible sans effacer ses fondements."},{"number":21,"points":21,"correct":"C","options":["Éviter d'identifier les sujets","Remplacer les informations par des adhésions","Permettre au lecteur d'apprécier leur position","Garantir que toute critique sera supprimée"],"passage":"Des habitants lancent une lettre locale parce que certaines initiatives ne sont jamais couvertes. Ils prévoient toutefois de mentionner leurs liens avec les associations présentées. La lettre indiquera qui a proposé le sujet et si un membre de la rédaction participe à l'activité présentée. Les lecteurs pourront demander d'autres points de vue. Le groupe souhaite conserver sa connaissance du quartier, tout en rendant visibles les relations qui peuvent influencer ses choix. Il ne prétend pas remplacer cette proximité par une absence de position impossible à garantir.","question":"Pourquoi annoncer ces liens ?","explanation":"Le passage indique : « Des habitants lancent une lettre locale parce que certaines initiatives ne sont jamais couvertes. Ils prévoient toutefois de mentionner leurs liens avec les associations présentées. » Cela justifie la réponse : Permettre au lecteur d'apprécier leur position."},{"number":22,"points":21,"correct":"D","options":["Supprimer les vérifications","Remplacer tous les journalistes","Décider du résultat avant l'enquête","Contribuer aux questions à examiner"],"passage":"Une rédaction organise ses reportages selon les questions du public, mais garde la décision sur les vérifications et les sources. La participation des lecteurs nourrit l'enquête sans en fixer d'avance la conclusion. Les journalistes regroupent les propositions, vérifient ce qui peut être étudié et expliquent les sujets qu'ils ne pourront pas traiter immédiatement. Certains lecteurs apportent des documents ou des observations utiles. La rédaction conserve toutefois la responsabilité de confronter ces éléments à d'autres sources.","question":"Quelle place est donnée aux lecteurs ?","explanation":"Le passage indique : « Une rédaction organise ses reportages selon les questions du public, mais garde la décision sur les vérifications et les sources. La participation des lecteurs nourrit l'enquête sans en fixer d'avance la conclusion. » Cela justifie la réponse : Contribuer aux questions à examiner."},{"number":23,"points":21,"correct":"A","options":["Un contexte ajouté de manière erronée","Une image entièrement inventée nécessairement","Une absence de toute scène visible","Une qualité technique trop faible uniquement"],"passage":"Une vidéo très partagée montre une scène réelle, mais le commentaire affirme qu'elle se déroule dans une autre ville. La fausseté ne se trouve pas dans l'image elle-même, mais dans son attribution. Les participants apprennent donc à rechercher l'origine de la vidéo et les publications antérieures. Ils comparent les détails visibles avec les lieux annoncés. Un document réel peut être utilisé pour soutenir une affirmation fausse si le contexte ajouté ne correspond pas à ce qui a été filmé.","question":"Quel problème est identifié ?","explanation":"Le passage indique : « Une vidéo très partagée montre une scène réelle, mais le commentaire affirme qu'elle se déroule dans une autre ville. La fausseté ne se trouve pas dans l'image elle-même, mais dans son attribution. » Cela justifie la réponse : Un contexte ajouté de manière erronée."},{"number":24,"points":21,"correct":"D","options":["Une identité connue doit toujours être publiée","La protection d'une source interdit tout entretien","L'anonymat impose de ne rien vérifier","Anonymat public et absence de vérification ne se confondent pas"],"passage":"Un média refuse de citer une personne de manière anonyme sans en connaître l'identité. Il peut protéger son nom publiquement tout en vérifiant qui fournit l'information. La rédaction évalue les raisons de la protection et cherche des confirmations indépendantes. Elle explique aux lecteurs la portée de ce choix sans révéler les informations permettant d'identifier la personne. L'objectif est de rendre possible un témoignage utile, tout en gardant une exigence de fiabilité.","question":"Quelle différence est faite ?","explanation":"Le passage indique : « Un média refuse de citer une personne de manière anonyme sans en connaître l'identité. Il peut protéger son nom publiquement tout en vérifiant qui fournit l'information. » Cela justifie la réponse : Anonymat public et absence de vérification ne se confondent pas."},{"number":25,"points":21,"correct":"A","options":["Parce que le nombre de partages renseigne sur l'attention, non la fiabilité.","Parce que la fréquence des partages révèle directement la méthode employée par l'auteur.","Parce qu'un contenu largement partagé ne peut être fondé sur une étude consultable.","Parce qu'un message vérifiable circule nécessairement moins vite qu'une information sans source."],"passage":"Un atelier explique qu'un nombre de partages mesure une circulation, pas une exactitude. Une information fausse peut être très visible, et une enquête fiable peu connue. Les participants comparent la circulation de plusieurs messages et cherchent les documents sur lesquels ils s'appuient. Certains contenus attirent surtout parce qu'ils surprennent ou confirment une opinion. Le groupe souhaite distinguer ces raisons de partage du travail nécessaire pour établir un fait. Deux articles circulent largement. Le premier cite une étude dont la méthode peut être consultée; le second reprend une rumeur sans document vérifiable. Le nombre de partages est proche, mais les fondements diffèrent.","question":"Pourquoi l'égalité de diffusion des deux messages ne permet-elle pas de conclure à leur fiabilité comparable ?","explanation":"La circulation et la vérification sont deux critères distincts. A. D/C/B infèrent un lien non établi."},{"number":26,"points":21,"correct":"C","options":["Écarter toutes ses observations car il ne contient pas de données suffisantes pour une moyenne nationale.","Le traiter comme un échantillon représentatif puisque les journalistes ont détaillé les circonstances.","Le traiter comme un cas détaillé sans lui attribuer une portée statistique nationale.","En déduire la part nationale des familles rencontrant le même problème à partir de l'année suivie."],"passage":"Un reportage suit une seule famille pendant une année. Il rend son expérience précise, mais les auteurs ne prétendent pas que toutes les familles vivent la même situation. Les journalistes montrent les choix quotidiens, les hésitations et les changements observés pendant le suivi. Ils présentent aussi les circonstances de cette rencontre, afin de ne pas donner l'illusion d'une famille choisie comme résumé de toute la société. Le reportage peut ainsi rendre sensible une expérience précise. Le reportage montre comment cette famille a modifié son budget après un déménagement. Les journalistes précisent que le récit ne permet pas d'estimer combien de familles vivent une situation similaire.","question":"Quelle utilisation de ce reportage est défendable ?","explanation":"L'étude détaillée d'un cas n'est ni une statistique représentative ni inutile. C. D/B généralisent; A rejette à tort sa valeur descriptive."},{"number":27,"points":21,"correct":"B","options":["Ne retenir que les conclusions les plus populaires afin de représenter l'opinion du public.","Hiérarchiser les affirmations selon l'état des preuves, tout en expliquant les désaccords encore ouverts.","Deux hypothèses qui peuvent être testées doivent recevoir la même place même lorsque leurs preuves diffèrent.","Un temps de parole égal reste acceptable si le présentateur signale brièvement les écarts de documentation."],"passage":"Une émission débat d'un désaccord scientifique. Le producteur distingue une controverse entre spécialistes et une affirmation isolée sans preuve. Donner un temps égal à toute affirmation ne produirait pas forcément une représentation équilibrée des connaissances. Les organisateurs consultent donc des travaux de référence et demandent aux invités de préciser leurs arguments. Ils ne souhaitent pas éliminer le désaccord, mais rendre visible ce qui le soutient. L'un des invités défend une hypothèse appuyée par plusieurs études; un autre avance une objection récente encore peu examinée. Le producteur prévoit de présenter les deux sans laisser croire qu'elles ont le même degré de confirmation.","question":"Quel principe évite une fausse équivalence entre les positions ?","explanation":"B demande d'exposer les désaccords en proportion de leurs fondements scientifiques. A favorise la popularité; C donne le même poids à des hypothèses inégalement étayées; D considère l'égalité du temps suffisante malgré les écarts de preuve."},{"number":28,"points":21,"correct":"C","options":["Il permet à la rédaction de retirer les sources pour alléger la lecture des non-spécialistes.","Il distingue les lecteurs qui disposent de peu de temps de ceux qui sont autorisés à examiner les sources.","Il offre un premier niveau de compréhension tout en maintenant l'accès aux preuves et aux nuances.","Il donne un aperçu suffisant pour affirmer connaître les limites et tous les documents du dossier."],"passage":"Un journal ajoute un résumé au début de ses enquêtes longues. Les lecteurs pressés disposent d'un repère, tandis que les détails restent consultables. La rédaction veut permettre une entrée plus facile dans un sujet complexe. Elle observera aussi si les lecteurs retrouvent les explications dont ils ont besoin. Une lecture rapide reste possible, mais elle ne doit pas être présentée comme nécessairement équivalente à l'examen complet du dossier et de ses limites. Certains lecteurs utilisent le résumé pour décider d'ouvrir le dossier complet, tandis que d'autres ne lisent que l'essentiel. La rédaction indique les limites de l'enquête dans le dossier et évite d'effacer cette possibilité d'approfondissement.","question":"Quelle fonction le résumé remplit-il sans se substituer à l'enquête ?","explanation":"Le résumé facilite l'entrée tout en laissant les détails disponibles. C. D/A/B déforment les degrés de lecture."},{"number":29,"points":21,"correct":"A","options":["Pour expliquer les arbitrages et les options écartées dans la décision.","Pour remplacer le procès-verbal par une liste de désaccords sans résultats.","Pour montrer que les membres absents approuvaient nécessairement les options finalement retenues.","Pour prouver que toutes les propositions étaient équivalentes avant le vote."],"passage":"Une association explique ses décisions dans un bulletin. Elle mentionne aussi les propositions non retenues et leurs raisons, afin que le compte rendu ne paraisse pas présenter un accord unanime fictif. Les membres absents peuvent ainsi comprendre pourquoi une décision a été prise et quelles difficultés ont été discutées. Le bulletin distingue les points d'accord et ceux qui restent ouverts. Le bulletin explique qu'une proposition de financement a été écartée non parce qu'elle manquait de soutien, mais parce qu'une condition juridique empêchait son application. Les membres absents peuvent comprendre la décision malgré ce désaccord.","question":"Pourquoi rendre compte des propositions rejetées ?","explanation":"Les raisons des refus rendent la décision transparente, A. D/B/C effacent les justifications ou inventent un accord."},{"number":30,"points":26,"correct":"D","options":["Vérifier uniquement que la citation provient du même intervenant et de la même date.","Une citation plus courte peut rester fidèle si le propos complet est disponible ailleurs pour les lecteurs.","Le nombre de mots authentiques permet d'évaluer si les restrictions modifient réellement la conclusion citée.","Comparer la formulation complète et les conditions qui déterminent le sens de la conclusion."],"passage":"Une phrase exacte peut devenir trompeuse lorsqu'elle est séparée de la condition qui la limitait. Un atelier demande donc de retrouver le passage complet avant de discuter une citation très courte. Vérifier les mots ne suffit pas toujours à vérifier le sens attribué. Les animateurs proposent des citations dont les mots sont authentiques mais le sens incomplet. Les participants peuvent alors examiner ce qui change lorsque l'on retrouve la question posée et la suite de la réponse. Une chercheuse déclare: « Cette mesure ne réduit pas le risque dans tous les cas. » Le titre d'un message viral ne retient que « Cette mesure réduit le risque » et supprime la négation de portée et la condition.","question":"Quelle vérification manque au lecteur qui confirme seulement que certains mots figurent dans l'entretien ?","explanation":"D exige de confronter la citation à la négation et aux conditions omises dans le passage complet. A ne vérifie que l'origine; B confond disponibilité du contexte ailleurs et fidélité du message viral; C comptabilise des mots sans vérifier le sens."},{"number":31,"points":26,"correct":"A","options":["Diffuser les faits confirmés et différer les annonces encore insuffisamment vérifiées.","Elle retarde toutes les nouvelles, y compris celles déjà vérifiées, jusqu'au lendemain.","Elle publie l'annonce incertaine en laissant aux lecteurs le soin d'en vérifier la source.","Elle refuse de corriger une information publiée avant la vérification complète."],"passage":"La rapidité est devenue un argument des médias. Une rédaction choisit pourtant de retarder une annonce lorsqu'une vérification essentielle manque. Elle ne renonce pas à informer, mais considère que publier avant de savoir peut créer une erreur difficile à corriger ensuite. Elle souhaite conserver une information utile au public, sans transformer le délai de vérification en silence total ni l'urgence de publier en excuse pour affirmer sans preuve. Une information urgente semble plausible mais dépend d'un document que la rédaction n'a pas pu confirmer. Elle publie ce qu'elle a vérifié et réserve l'annonce contestée pour un point ultérieur.","question":"Comment la rédaction concilie-t-elle rapidité et responsabilité ?","explanation":"Elle informe dans la limite de ce qui est confirmé, A. B/C/D ne respectent pas le compromis décrit."},{"number":32,"points":26,"correct":"A","options":["Les valeurs ne changent pas avec l'échelle, mais l'impression de grandeur dépend de la représentation.","Deux axes différents produisent des variations numériques distinctes pour les mêmes données.","La seconde échelle atténue la hausse visuelle, ce qui rend le changement observé moins significatif dans les données.","Le premier graphique amplifie la hausse, tandis que le second corrige la valeur mesurée par une échelle plus complète."],"passage":"Un graphique commence son axe vertical au-dessus de zéro. Ce choix peut rendre une variation plus visible. Il n'est pas forcément illégitime, mais doit être compris : une impression de rupture spectaculaire peut venir en partie de l'échelle choisie. Les lecteurs peuvent comparer plusieurs échelles à partir des mêmes valeurs. Le cours veut rendre ces choix compréhensibles plutôt que demander de se fier uniquement à l'impression immédiate produite par la hauteur de deux colonnes. Les valeurs passent de 98 à 100. Sur un axe commençant à 97, les colonnes semblent différer énormément; sur un axe commençant à zéro, leur différence paraît modeste. Les nombres eux-mêmes restent identiques.","question":"Quelle distinction permet de lire correctement les deux graphiques ?","explanation":"A distingue les données 98 et 100 de leur apparence selon l'axe choisi. B et D attribuent à l'échelle un changement des valeurs elles-mêmes; C infère une moindre signification statistique de la seule présentation visuelle."},{"number":33,"points":26,"correct":"C","options":["Elles prouvent qu'une relation ancienne avec un élu rend chaque article favorable à cet élu.","Elles obligent les journalistes à rompre toutes leurs relations locales pour préserver l'indépendance.","Elles permettent de contrôler les informations malgré la proximité des sources, dans chaque article.","Elles rendent inutile toute critique, puisque les informations ont été obtenues par un contact régulier."],"passage":"Un journal local entretient des relations régulières avec les acteurs qu'il couvre. Cette proximité facilite l'accès aux informations, mais peut rendre une critique délicate. L'équipe formalise ses règles pour préserver une indépendance qui ne dépend pas de l'absence totale de contacts. Le journal souhaite que la confiance se construise sur des pratiques visibles, pas seulement sur l'affirmation générale de son indépendance dans une présentation officielle. Une journaliste connaît depuis longtemps les responsables municipaux, ce qui facilite les entretiens. Pour examiner un contrat contesté, elle conserve les documents et les critères de vérification accessibles à ses collègues.","question":"Pourquoi les règles éditoriales explicites comptent-elles dans un contexte de proximité ?","explanation":"La proximité peut aider l'accès tout en créant un risque; des règles vérifiables protègent le jugement. C. B/A/D exagèrent ou nient ce risque."},{"number":34,"points":26,"correct":"B","options":["Une note exacte rétablit la fiabilité malgré les captures d'écran initiales.","La correction reste peu utile si les lecteurs initiaux ne la voient pas.","Le public peut consulter la note correcte; sa précision compense donc sa faible visibilité auprès des lecteurs initiaux.","Il vaut mieux diffuser le correctif à de nouveaux lecteurs qu'identifier ceux qui avaient été exposés à l'article erroné."],"passage":"Une correction atteint souvent moins de lecteurs que le message initial. Des journalistes réfléchissent donc à la manière de la diffuser auprès du même public. Reconnaître l'erreur constitue une étape ; réparer son effet demande aussi de regarder sa circulation. Elle vérifiera la visibilité du correctif, plutôt que considérer le travail terminé dès qu'une note exacte a été placée dans une rubrique peu consultée. Un correctif discret est publié en fin de journée, mais l'article erroné continue de circuler sous forme de captures d'écran. La rédaction cherche à signaler la correction aux lecteurs exposés au message initial.","question":"Pourquoi publier une note exacte sur une page peu consultée ne règle-t-il pas entièrement l'erreur ?","explanation":"B relève qu'une note exacte ne corrige pas les impressions des lecteurs qui ne la rencontrent pas. A suppose un effet automatique malgré les captures, C confond accessibilité théorique et visibilité, D détourne la diffusion du public initialement exposé."},{"number":35,"points":26,"correct":"C","options":["Le témoignage situe la tendance sur le terrain et permet d'en déduire combien de résidents vivent la même situation.","La carte établit le phénomène général tandis que le témoignage en confirme directement l'ampleur dans le quartier.","Les chiffres situent une tendance et le témoignage illustre un effet particulier, dans une expérience de vie singulière.","La carte et le récit donnent deux estimations quantitatives de la même tendance qui peuvent être additionnées."],"passage":"Une enquête associe cartes, témoignages et documents. Aucun support n'épuise le sujet : les chiffres situent une tendance, tandis qu'un récit montre ses conséquences dans une vie. Leur combinaison devient utile si le lecteur comprend ce que chaque élément permet réellement d'affirmer. Le lecteur peut ainsi comprendre comment les éléments se complètent, sans attribuer à une histoire singulière la représentativité d'une enquête ni aux nombres la précision d'un récit individuel. Une carte signale une hausse de fréquentation, tandis qu'un habitant raconte comment cette évolution affecte son trajet. Le journaliste précise qu'un seul témoignage ne mesure pas la proportion d'habitants touchés.","question":"Quelle lecture combine correctement les deux sources ?","explanation":"C distingue la portée de la carte et celle du témoignage individuel. A et B infèrent une représentativité non mesurée par le récit; D traite un récit qualitatif comme une seconde estimation numérique."},{"number":36,"points":33,"correct":"B","options":["L'obligation d'obtenir davantage de documents de référence avant d'inviter des personnes non représentées.","La confusion entre visibilité médiatique et pertinence des personnes touchées par la décision.","La tendance à sélectionner les groupes qui comptent le plus de membres, sans examiner leur rapport au problème.","La difficulté de comparer les expériences des participants lorsque chacun intervient dans un cadre médiatique différent."],"passage":"Une rédaction veut représenter équitablement un débat. Elle invite les acteurs les plus visibles, puis découvre que certains habitants directement concernés ne disposent d'aucun porte-parole organisé. La visibilité publique n'est pas une mesure suffisante de l'importance d'un point de vue dans une situation. Les journalistes vont rechercher ces personnes avec des relais locaux et proposer plusieurs façons de répondre. Certaines ne souhaitent pas intervenir sur un plateau mais peuvent expliquer leur expérience dans un autre cadre. La rédaction veut éviter que son calendrier et ses habitudes de contact ne déterminent seuls les voix entendues. Les acteurs déjà présents ne seront pas écartés pour autant. Le dossier sera construit à partir des intérêts en jeu et des personnes concernées, plutôt qu'à partir d'une liste de porte-parole faciles à joindre et habitués à parler dans les médias. Les invités habituels sont facilement joignables, mais les travailleurs concernés par le nouveau règlement n'ont pas d'organisation qui les représente. Le journal prévoit des entretiens hors studio pour entendre leurs expériences.","question":"Quel biais de sélection la rédaction tente-t-elle de corriger ?","explanation":"B désigne le biais de visibilité médiatique, qui écarte des personnes directement touchées. A confond vérification et sélection; C remplace visibilité par taille des groupes; D évoque une question de comparaison, non l'absence de voix."},{"number":37,"points":33,"correct":"B","options":["Une sélection de sujet ne peut être jugée rigoureuse que si la rédaction ne rend pas publics ses critères.","Discuter du choix des sujets tout en vérifiant les faits à partir de sources consultables.","La transparence des priorités éditoriales rend secondaires les preuves citées pour établir les faits.","L'existence de sources vérifiables garantit que la sélection des sujets ne reflète aucune priorité éditoriale."],"passage":"Un média explique ses choix de sujets. Certains lecteurs y voient un aveu de subjectivité qui invaliderait toute information. La rédaction répond que sélectionner est inévitable, mais que les critères peuvent être discutés et les faits vérifiés. Reconnaître un point de vue de travail ne revient pas à déclarer que toutes les affirmations se valent. Elle présente les critères qui l'ont conduite à suivre un événement et les moyens utilisés pour vérifier les informations. Les lecteurs peuvent contester ces choix ou proposer des sujets absents. La rédaction souhaite conserver cette discussion sans confondre critique des priorités et rejet de toute possibilité d'établir des faits. Certaines questions restent ouvertes, d'autres peuvent recevoir des réponses mieux appuyées que de simples impressions. Les sources restent consultables. Le média explique pourquoi il suit un conflit local et met à disposition les documents qu'il cite. Des lecteurs peuvent discuter du choix du sujet, tout en vérifiant séparément si un fait précis est étayé.","question":"Quel rapport la rédaction établit-elle entre sélection éditoriale et vérification ?","explanation":"B sépare la discussion des priorités et la vérification des faits. A et D attribuent à la sélection des propriétés infondées; C rend les preuves secondaires alors qu'elles sont maintenues."},{"number":38,"points":33,"correct":"A","options":["Présenter un accès local et conditionnel comme universel, sans préciser les communes ni les dates concernées.","Elle transformait une condition administrative secondaire en une restriction décisive dont le public ne pouvait comprendre l'origine.","Elle risquait de décourager les lecteurs en donnant trop de place à des critères géographiques clairement définis.","Elle présentait une offre trop limitée alors que les possibilités d'inscription étaient plus larges que prévu."],"passage":"Une campagne de communication cherche un message très simple. Les responsables retirent successivement les réserves jusqu'à produire une promesse plus forte que le projet réel. La clarté devient trompeuse lorsqu'elle efface précisément les conditions qui déterminent la validité de ce qu'elle annonce. L'équipe compare la formule finale aux engagements réellement possibles et réintroduit les limites importantes. Elle veut garder un message lisible, mais aussi permettre au destinataire de savoir si l'offre correspond à sa situation. Des exemples courts peuvent parfois être plus utiles qu'une promesse très large suivie d'une longue liste de réserves difficiles à trouver. Le projet sera donc présenté avec ses conditions principales au même endroit. La communication ne remplace pas la réalisation, mais elle influence les attentes à partir desquelles les personnes jugeront ensuite ce qui a effectivement été fait. Le message publicitaire initial annonce « disponible pour tous ». Le service est en réalité réservé aux résidents de trois communes à certaines dates. L'équipe réintroduit ces conditions à proximité de l'annonce.","question":"Quelle erreur la version initiale du message risquait-elle de produire ?","explanation":"A constate qu'une promesse générale omettait des critères d'accès essentiels. B minimise faussement ces critères, C suppose qu'ils étaient détaillés, D inverse l'écart entre annonce et offre réelle."},{"number":39,"points":33,"correct":"B","options":["Les réactions initiales sont un indicateur de valeur éditoriale fiable, mais elles doivent être ajustées au nombre de consultations différées.","L'intérêt durable peut échapper au classement initial, sans que ces observations prouvent l'effet qu'aurait eu un autre algorithme sur l'audience.","Les visites tardives montrent que le classement algorithmique avait empêché la seconde enquête de rejoindre son public.","L'exemple de deux enquêtes démontre que les lecteurs préfèrent généralement les analyses longues aux textes suscitant des réactions rapides."],"passage":"Les plateformes recommandent souvent des contenus suscitant une réaction rapide. Une enquête complexe demande au contraire du temps avant de produire une conclusion. Évaluer tous les contenus par la réaction immédiate risque de défavoriser des formes d'information dont l'intérêt apparaît au cours d'une lecture attentive. Le média expérimente des présentations qui aident à entrer dans ces sujets sans les réduire à une formule provocante. Il observe aussi les lectures achevées et les retours plus tardifs. Les responsables souhaitent éviter qu'un travail utile mais lent à produire une réaction soit systématiquement moins visible. Ils ne demandent pas d'ignorer l'intérêt du public. Ils cherchent d'autres manières de le comprendre, en tenant compte du temps nécessaire pour découvrir une question complexe. Les choix de recommandation doivent ainsi être discutés avec les effets qu'ils produisent sur les informations accessibles, pas seulement avec le nombre de clics obtenus dans les premières secondes. Une enquête soigneusement vérifiée reçoit peu de clics le premier jour mais est largement lue et discutée les semaines suivantes. Les responsables envisagent un indicateur de lecture achevée et des retours différés. Le média suit ensuite deux enquêtes comparables publiées à un mois d'intervalle. La première reçoit beaucoup de réactions dans les deux premières heures, puis presque aucune lecture menée jusqu'au bout. La seconde reçoit peu de réactions initiales, mais ses lectures achevées progressent pendant trois semaines et plusieurs associations la citent lors de réunions publiques. Les responsables observent aussi que certaines visites tardives proviennent de partages entre lecteurs et non des recommandations automatiques. Ils ne disposent pas d'une expérience où le même article aurait été recommandé selon deux règles différentes. Ils évitent donc de présenter la seconde enquête comme la preuve qu'un autre algorithme augmenterait nécessairement son audience. Ils veulent plutôt savoir si l'indicateur retenu pour classer les articles capture la forme d'attention qu'ils cherchent à favoriser, au lieu de confondre toute consultation tardive avec une réaction immédiate manquée.","question":"Que montre le rapprochement des deux enquêtes, et quelle conclusion serait excessive ?","explanation":"B constate que l'attention durable peut apparaître tard tout en refusant d'attribuer à un algorithme un effet non testé. A surestime la réaction immédiate; C en déduit un blocage algorithmique non prouvé; D généralise la préférence de tous les lecteurs à partir de deux articles."}]}$paper_14$::jsonb);
do $check_and_activate$
declare rec record; n integer; oldq jsonb; newq jsonb; correct_index integer; changed_rows integer;
begin
 for rec in select p.id, p.content as new_content, old.content as old_content, s.changed
 from academy_tcf_reading.papers p
 join academy_tcf_reading.papers old on old.id=p.id and old.version='tcf-reading-2026-11-close-reading-v4'
 join cleanup_scope s on s.test_id=p.id
 where p.version='tcf-reading-2026-11-distractor-polish-v5'
 loop
   if (rec.new_content - 'questions' - 'version') <> (rec.old_content - 'questions' - 'version')
   then raise exception 'Non-question paper metadata modified %',rec.id; end if;
   if jsonb_array_length(rec.new_content->'questions')<>39 or (rec.new_content->>'maxPoints')::integer<>699 or (rec.new_content->>'seconds')::integer<>3600
   then raise exception 'Test structure modified %',rec.id; end if;
   for n in 1..39 loop
     newq=rec.new_content->'questions'->(n-1);
     oldq=rec.old_content->'questions'->(n-1);
     if not (n=any(rec.changed)) then
       if newq<>oldq then raise exception 'Untargeted question changed % Q%',rec.id,n; end if;
     else
       if (newq - 'options' - 'explanation') <> (oldq - 'options' - 'explanation')
       then raise exception 'Passage, stem, key, scoring, or extra metadata changed % Q%',rec.id,n; end if;
       correct_index=case newq->>'correct' when 'A' then 0 when 'B' then 1 when 'C' then 2 when 'D' then 3 else -1 end;
       if correct_index<0 or newq->'options'->>correct_index <> oldq->'options'->>correct_index
       then raise exception 'Correct answer changed % Q%',rec.id,n; end if;
     end if;
   end loop;
 end loop;
 update academy_tcf_reading.published_papers set version='tcf-reading-2026-11-distractor-polish-v5'
 where test_id in ('tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14') and version='tcf-reading-2026-11-close-reading-v4';
 get diagnostics changed_rows=row_count;
 if changed_rows<>4 then raise exception 'Expected 4 pointer updates, got %',changed_rows; end if;
end $check_and_activate$;
do $postcheck$ begin
 if (select count(*) from academy_tcf_reading.published_papers)<>20 then raise exception 'Catalog was modified'; end if;
 if (select count(*) from academy_tcf_reading.published_papers where test_id in ('tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14') and version='tcf-reading-2026-11-distractor-polish-v5')<>4 then raise exception 'Target catalog not updated'; end if;
 if exists((select test_id,version from cleanup_other_pointers except select test_id,version from academy_tcf_reading.published_papers)
 union all (select test_id,version from academy_tcf_reading.published_papers where test_id not in ('tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14') except select test_id,version from cleanup_other_pointers)) then raise exception 'Other tests changed'; end if;
 if (select count(*) from academy_tcf_reading.papers)<>(select banks+4 from cleanup_before) then raise exception 'Historical bank row count changed'; end if;
 if (select md5(coalesce(string_agg(to_jsonb(p)::text,'' order by id,version),'')) from academy_tcf_reading.papers p where not (id in ('tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14') and version='tcf-reading-2026-11-distractor-polish-v5'))<>(select banks_digest from cleanup_before) then raise exception 'Historical bank data changed'; end if;
 if (select count(*) from academy_tcf_reading.attempts)<>(select attempts from cleanup_before) or
 (select md5(coalesce(string_agg(to_jsonb(a)::text,'' order by id),'')) from academy_tcf_reading.attempts a)<>(select attempts_digest from cleanup_before) then raise exception 'Student attempts changed'; end if;
end $postcheck$;
commit;